insert into private.study_guides (guide, chunks, sha256) values ('study_guide_ams101', 34, '7fb3c1eba64b4d367c0941d7a231ce30687c77968ae20b59e70f87596541edb3');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 1, $study_guide${"guide":"study_guide_ams101","code":"AMS101","courseId":"fa9abff6-1f94-5735-bbd3-c9104da6df05","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"01056477-565c-5c2d-ba31-ab08932bca13","create":true,"after":{"title":"Principles of Management","body":"The exam is mostly objective (CBT). Be ready for some theory questions too, where you define, list and explain.","outcomes":["Explain who managers are, what they do, and how management thinking developed.","Describe the environment managers work in, including culture, globalization, social responsibility and ethics.","Apply the decision-making process and explain how managers plan and choose strategies.","Describe the elements of organizational structure and compare common organizational designs.","Outline the human resource management process, from planning and hiring to appraisal and pay.","Explain why organizations change, how people react to change, and how managers encourage innovation.","Explain what shapes individual behaviour and how groups and teams work.","Compare the main theories of motivation and how managers reward employees.","Compare the main theories of leadership and explain how managers communicate and manage information.","Explain the control process and the basics of operations management."],"assessment":["Continuous assessment (tests and assignments): 30 to 40 marks.","Final exam: 60 to 70 marks, lasting 2 to 3 hours.","You need at least 65% lecture attendance to sit the exam."]}},"retire":[],"notes":[{"kind":"note","itemId":"bce825f0-4027-5787-94c8-cc1c107cf052","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Managers and Management","body":"Managers and their three levels; efficiency, effectiveness and the functions; Mintzberg's roles and Katz's skills; why study management; science or art; history.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"Managers and their three levels; efficiency, effectiveness and the functions; Mintzberg's roles and Katz's skills; why study management; science or art; history."}],"lessons":[{"number":"1.1","title":"Organizations, managers and levels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organization:","bold":true},{"text":" a deliberate arrangement of people to accomplish a specific purpose. Not a building, a mere group, or only profit-makers."}]},{"text":[{"text":"3 characteristics:","bold":true},{"text":" "},{"text":"goals","bold":true},{"text":" (purpose), "},{"text":"people","bold":true},{"text":", a deliberate "},{"text":"structure","bold":true},{"text":" (rules, regulations, values) that defines how members relate to one another at work. A student fraternity qualifies."}]},{"text":[{"text":"Nonmanagerial employees","bold":true},{"text":" do not direct or oversee others."}]},{"text":[{"text":"Manager:","bold":true},{"text":" works with and through others, directing and overseeing their activities. "},{"text":"Coordinating and integrating others' work","bold":true},{"text":" makes a job managerial. Managers may also do ordinary tasks. Managers get the chance to think creatively and use their imagination."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Top (strategic):","bold":true},{"text":" whole-organization decisions: vision, mission, long-term goals, policy, budgets. Board of Directors, chairperson, CEO, COO, executive vice president."}]},{"text":[{"text":"Middle (tactical):","bold":true},{"text":" between first-line and top; the link. Interpret directives, implement policies, turn goals into action, coordinate departments. Department head, division manager, plant manager, agency head, project leader, functional manager."}]},{"text":[{"text":"First-line (lower, supervisory, operational):","bold":true},{"text":" supervise workers: daily operations, routine decisions, training, performance. Report to middle managers. Focus on employee efficiency and motivation. Day-to-day administration of policies is operational (first-line) management's work. Supervisor, team leader, shift manager."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First-line is the lowest level of management; where it is not offered, a middle manager is the lowest level listed (nonmanagerial staff are not a management level). Coordinating departments is "},{"text":"not","bold":true},{"text":" a top-level job."}]},{"text":[{"text":"Newer organizations are more "},{"text":"dynamic","bold":true},{"text":"; managers are more varied in age, background and gender."}]}]}]},{"number":"1.2","title":"Management, efficiency, effectiveness and the functions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Management:","bold":true},{"text":" the process of getting things done effectively and efficiently, with and through people. Also: coordinating resources (planning, organizing, leading, controlling) to achieve goals. Organizational success depends on efficient management of resources; the main aim is organizational goals. It helps organizations achieve goals with minimal resources."}]},{"text":[{"text":"Efficiency:","bold":true},{"text":" doing things "},{"text":"right","bold":true},{"text":"; the "},{"text":"means","bold":true},{"text":". Relation of inputs to outputs: most output from least input; cutting cost while reaching goals."}]},{"text":[{"text":"Effectiveness:","bold":true},{"text":" doing the "},{"text":"right things","bold":true},{"text":"; the "},{"text":"ends","bold":true},{"text":". Attaining goals, e.g. delivering before the deadline."}]},{"text":[{"text":"Good management needs "},{"text":"both","bold":true},{"text":" high. Same sweets at lower cost = efficient, "},{"text":"not","bold":true},{"text":" more effective. Better sweets at lower cost = both. Effective management achieves organizational goals efficiently, never wasting resources. More cars at the same cost but full of defects = efficient only."}]},{"text":[{"text":"Henri Fayol","bold":true},{"text":" ($study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 2, $study_guide$French industrialist) gave "},{"text":"5 functions:","bold":true},{"text":" planning, organizing, commanding, coordinating, controlling. Today "},{"text":"4 (POLC):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"P","bold":true},{"text":"lanning (first): setting goals and how to reach them: objectives, strategy, forecasting, decision-making, timelines, mission and vision."}]},{"text":[{"text":"O","bold":true},{"text":"rganizing: structuring work: grouping tasks, allocating resources, assigning duties, delegating authority, organizational chart."}]},{"text":[{"text":"L","bold":true},{"text":"eading (= directing): influencing, motivating, communicating, mentoring, settling conflict. "},{"text":"Motivation","bold":true},{"text":" = encouraging employees to work. "},{"text":"Delegation","bold":true},{"text":" = assigning duties and responsibilities to employees."}]},{"text":[{"text":"C","bold":true},{"text":"ontrolling (last): monitoring, comparing, correcting; evaluating results; ensures all activities are aligned with organizational objectives and tasks are done correctly and on time."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Not","bold":true},{"text":" functions: innovating; departmentalization (part of organizing)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Directing","bold":true},{"text":" initiates action (other functions prepare the setting). It is continuous and flows top to bottom: a manager directs his subordinate and takes instructions from his boss."}]},{"text":[{"text":"Staffing:","bold":true},{"text":" recruiting, selecting, training, appraising, retaining: the right number and mix of people in the right positions. Budgeting is "},{"text":"not","bold":true},{"text":" staffing."}]},{"text":[{"text":"Coordinating:","bold":true},{"text":" synergizing the efforts of separate units to reach goals. It "},{"text":"is","bold":true},{"text":" a management function, relates to organizing, needs leadership. Needed because of task specialization, human differences, task dependency. Mechanisms: rules and procedures, plans and goals, management hierarchy (\"organization\" is not one). "},{"text":"External","bold":true},{"text":" coordination is with outside stakeholders. Problems: poor communication, differing leadership styles, differing formality of structure; not acceptable plans. Lack of commitment causes failure."}]},{"text":[{"text":"Management is "},{"text":"continuous","bold":true},{"text":"; a good manager communicates well. Management thought grew with socio-economic development, managers' experience and thinkers' foundations."}]}]}]},{"number":"1.3","title":"Roles, skills and universality","mustKnow":[{"type":"paragraph","text":[{"text":"Mintzberg's 10 roles","bold":true},{"text":" (from closely studying "},{"text":"5 chief executives","bold":true},{"text":"), in 3 groups:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Interpersonal (3):","bold":true},{"text":" figurehead, leader, liaison."}]},{"text":[{"text":"Informational (3):","bold":true},{"text":" monitor, disseminator, spokesperson."}]},{"text":[{"text":"Decisional (4):","bold":true},{"text":" entrepreneur, disturbance handler, resource allocator, negotiator."}]},{"text":[{"text":"Interpersonal = dealing with people, ceremonial and symbolic duties. Informational = receiving, gathering, spreading information. Decisional = decisions. \"Technical\" is not a role."}]},{"text":[{"text":"Dinner speech = figurehead. Attending a professional or scientists' meeting = liaison. Reading business newspapers = monitor. Negotiator is decisional: decides when to compromise."}]}]},{"type":"paragraph","text":[{"text":"Katz's skills:","bold":true},{"text":" technical, human (interpersonal), conceptual. The four-skill version adds "},{"text":"political","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Technical:","bold":true},{"text":" job-specific (building codes, computer programming); matters most at first-line."}]},{"text":[{"text":"Human:","bold":true},{"text":" getting along with and motivating people; needed at all levels."}]},{"text":[{"text":"Conceptual:","bold":true},{"text":" abstract thinking, seeing the whole, applying information to solve problems; matters most at top."}]},{"text":[{"text":"Political:","bold":true},{"text":" networking, building a power base; for those moving up."}]}]},{"type":"paragraph","text":[{"text":"Universality:","bold":true},{"text":" all managers make decisions and do the 4 functions, but not identically. Emphasis varies with "},{"text":"level","bold":true},{"text":", "},{"text":"profit vs nonprofit","bold":true},{"text":", "},{"text":"size","bold":true},{"text":", "},{"text":"country","bold":true},{"text":". Almost every task involves a decision."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Mintzberg's surprise: managers spent only a short time on each activity."}]},{"text":[{"text":"All three interpersonal roles fit "},{"text":"leading","bold":true},{"text":"; resource allocator fits "},{"text":"planning","bold":true},{"text":". Higher levels stress figurehead, liaison, disseminator, spokesperson, negotiator; lower levels stress "},{"text":"leader","bold":true},{"text":"."}]},{"text":[{"text":"As managers rise, technical skill matters less; human skill stays needed. A president needs technical skill least. Managers with strong "},{"text":"human skills bring out the best in their people","bold":true},{"text":"."}]},{"text":[{"text":"Political skill: networking, social astuteness, sincerity; not a dominant personality."}]},{"text":[{"text":"Nonprofits","bold":true},{"text":" differ in how they "},{"text":"judge success","bold":true},{"text":"; tight budgets demand efficiency."}]},{"text":[{"text":"Small business:","bold":true},{"text":" under 500 staff and no major industry influence. Manager is a "},{"text":"generalist","bold$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 3, $study_guide$":true},{"text":"; "},{"text":"spokesperson","bold":true},{"text":" matters more. Informal, simpler design; control by direct observation, not computerised monitoring. Large firms focus internally, on "},{"text":"resource allocation","bold":true},{"text":"."}]}]}]},{"number":"1.4","title":"Why study management; science or art","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"2 reasons:","bold":true},{"text":" (1) we deal with organizations every day; (2) you will manage or be managed. Well-managed organizations prosper in hard times through a "},{"text":"loyal customer base","bold":true},{"text":"."}]},{"text":[{"text":"Universality of management:","bold":true},{"text":" needed in every type and size of organization, level, work area and country."}]},{"text":[{"text":"4 forces:","bold":true},{"text":" changing workplaces, ethics and trust (including "},{"text":"mistrust between managers and employees","bold":true},{"text":"), economic and political uncertainty, changing technology. Key areas: "},{"text":"customers","bold":true},{"text":", "},{"text":"innovation","bold":true},{"text":". Employees who are unwilling to work is "},{"text":"not","bold":true},{"text":" one of these forces."}]},{"text":[{"text":"Management is "},{"text":"both","bold":true},{"text":" a science and an art."}]},{"text":[{"text":"Science","bold":true},{"text":" (objective): systematic knowledge and universal principles; clear guidelines; systematic planning; decision-making based on data; experimentation, observation, facts; measured and tested; removes bias; predictable, consistent results; applies to any organization; e.g. time and motion study."}]},{"text":[{"text":"Art","bold":true},{"text":" (subjective): practical skill and personal judgement; creativity, innovation, intuition, vision, experience, talent; improves with continuous practice; develops unique solutions; matters most in strategic decision-making; motivation, leadership style, conflict resolution. \"An art of getting things done\" means it requires human skills."}]},{"text":[{"text":"Both","bold":true},{"text":" because it combines creativity (art) and structure (science)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"It is an "},{"text":"inexact science","bold":true},{"text":" because it deals with human behaviour. "},{"text":"Mintzberg","bold":true},{"text":" stressed the art side. Trial and error is "},{"text":"not","bold":true},{"text":" scientific."}]},{"text":[{"text":"Scientific management (productivity, standard work methods, data) is criticised as "},{"text":"mechanistic and rigid","bold":true},{"text":", ignoring human aspects."}]},{"text":[{"text":"Management is often hard and thankless; success depends on how well "},{"text":"others","bold":true},{"text":" perform. Managers create an environment where members work to their best, think creatively, and rely on "},{"text":"every member","bold":true},{"text":" to raise productivity. The direct-supervisor relationship is the biggest factor in productivity and loyalty."}]},{"text":[{"text":"Hardest ethical challenge: laying off hardworking, productive staff."}]},{"text":[{"text":"Customer satisfaction is increasingly a key goal; a prompt, helpful human answer shows responsiveness. "},{"text":"Innovation","bold":true},{"text":" gives an advantage over competitors."}]},{"text":[{"text":"C.K. Prahalad","bold":true},{"text":" introduced \"core competency\". A football fan gains least."}]}]}]},{"number":"1.5","title":"History of management","mustKnow":[{"type":"paragraph","text":[{"text":"Management is ancient; its study as a discipline began in the "},{"text":"20th century","bold":true},{"text":". Five eras:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Early:","bold":true},{"text":" Arsenal of Venice, "},{"text":"Adam Smith","bold":true},{"text":" ("},{"text":"Wealth of Nations","italic":true},{"text":", division of labour), Industrial Revolution (machine power replaced human power)."}]},{"text":[{"text":"Classical:","bold":true},{"text":" "},{"text":"Taylor","bold":true},{"text":" (scientific management, \"one best way\"; focus on process efficiency), "},{"text":"Gilbreths","bold":true},{"text":", "},{"text":"Fayol","bold":true},{"text":", "},{"text":"Weber","bold":true},{"text":" (bureaucracy)."}]},{"text":[{"text":"Behavioural (OB):","bold":true},{"text":" "},{"text":"Owen","bold":true},{"text":" (working conditions), "},{"text":"Munsterberg","bold":true},{"text":" (industrial psychology), "},{"text":"Follett","bold":true},{"text":" (individual and group behaviour), "},{"text":"Barnard","bold":true},{"text":" (cooperative social systems; first to call organizations open systems), "},{"text":"Hawthorne Studies","bold":true},{"text":" (Mayo; the most important contribution to the growth of organizational behaviour)."}]},{"text":[{"text":"Quantitative:","bold":true},{"text":" operations research / management science, from World War II; "},{"text":"TQM","bold":true},{"text":" (total quality management, the quality revolution of the 1980s-90s)."}]},{"text":[{"text":"Contemporary:","bold":true},{"text":" systems, contingency (\"it depends\"), information technology."}]}]},{"type":"paragraph","text":[{"text":"Four approaches of the early 20th century: scientific management, general administrative, quantitative, OB. Systems is "},{"text":"not","bold":true},{"text":" one."}]},{"type":"paragraph","text":[{"text":"Fayol's 14 principles:","bold":true},{"text":" division of work · authority · discipline · unity of command · unity of direction · subordination of individual interest · remuneration · centralization · scalar chain · order · equity · stability of tenure · initiative · esprit de corps. \"Equality\" and \"monopoly\" are "},{"text":"not","bold":true},{"text":" principles."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Division of work:","bold":true},{"text":" tasks by skill (specialization); raises effi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 4, $study_guide$ciency."}]},{"text":[{"text":"Authority:","bold":true},{"text":" right to give orders and expect obedience; balanced with responsibility."}]},{"text":[{"text":"Discipline:","bold":true},{"text":" respect for agreements and rules. "},{"text":"Remuneration:","bold":true},{"text":" fair pay."}]},{"text":[{"text":"Unity of command:","bold":true},{"text":" one boss; gives clear lines of authority and reduces confusion. "},{"text":"Unity of direction:","bold":true},{"text":" common objectives."}]},{"text":[{"text":"Scalar chain:","bold":true},{"text":" line of authority top to bottom. "},{"text":"Esprit de corps:","bold":true},{"text":" team spirit."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Smith:","bold":true},{"text":" division of labour raises productivity: more skill and dexterity, less time lost switching tasks, labour-saving inventions (not strict control of time)."}]},{"text":[{"text":"Taylor:","bold":true},{"text":" Pennsylvania steel companies; shocked that workers used different methods, took it easy, produced only about a third of what they could, and were placed regardless of ability. Concern: "},{"text":"worker efficiency","bold":true},{"text":". Study: "},{"text":"pig iron","bold":true},{"text":". Recommended "},{"text":"incentive pay","bold":true},{"text":"."}]},{"text":[{"text":"Gilbreths:","bold":true},{"text":" began with "},{"text":"bricklaying","bold":true},{"text":"; used motion pictures to study hand and body motions; "},{"text":"therbligs","bold":true},{"text":" = basic hand motions."}]},{"text":[{"text":"General administrative theory","bold":true},{"text":" (Fayol, Weber): the whole organization. Fayol studied "},{"text":"macro","bold":true},{"text":" issues, Taylor "},{"text":"micro","bold":true},{"text":"."}]},{"text":[{"text":"Weber's bureaucracy:","bold":true},{"text":" division of labour, hierarchy, detailed rules, impersonality, "},{"text":"formal selection","bold":true},{"text":" (choosing people for jobs on the basis of their "},{"text":"technical qualifications","bold":true},{"text":"), career orientation."}]},{"text":[{"text":"OB","bold":true},{"text":" is linked with motivation. Munsterberg links with scientific management; work groups trace to Follett."}]},{"text":[{"text":"Hawthorne:","bold":true},{"text":" began as "},{"text":"lighting","bold":true},{"text":" tests; group norms drive individual behaviour; productivity and human relations."}]},{"text":[{"text":"Quantitative:","bold":true},{"text":" from WWII military problems. "},{"text":"Linear programming","bold":true},{"text":" allocates resources; "},{"text":"EOQ","bold":true},{"text":" sets inventory levels. Motivating individuals is "},{"text":"not","bold":true},{"text":" quantitative."}]},{"text":[{"text":"TQM","bold":true},{"text":" (quality management; "},{"text":"Deming and Juran","bold":true},{"text":"): continual improvement, customer needs; costs can fall while productivity rises."}]},{"text":[{"text":"Contingency:","bold":true},{"text":" flexible, no one best way."}]},{"text":[{"text":"Trends:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Workforce diversity:","bold":true},{"text":" gender, race, age and more. "},{"text":"Learning organization:","bold":true},{"text":" keeps learning, adapting, changing. "},{"text":"Knowledge management:","bold":true},{"text":" members systematically gather and share knowledge."}]},{"text":[{"text":"Entrepreneurship:","bold":true},{"text":" exploiting opportunities others have not noticed. 3 themes: pursuing opportunities, innovation, growth."}]},{"text":[{"text":"E-business:","bold":true},{"text":" the organization's work through internet links; "},{"text":"e-commerce","bold":true},{"text":" is its sales and marketing side. Levels: "},{"text":"enhanced","bold":true},{"text":", "},{"text":"enabled","bold":true},{"text":" (internet improves traditional work, no online selling), "},{"text":"total","bold":true},{"text":" (revolves around the internet). "},{"text":"Intranet:","bold":true},{"text":" internal network for employees only."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organization = goals + people + structure."}]},{"text":[{"text":"Management = efficient (means), effective (ends) work through people."}]},{"text":[{"text":"Fayol's 5 functions became "},{"text":"POLC","bold":true},{"text":"; directing = leading."}]},{"text":[{"text":"Mintzberg: 10 roles (3 interpersonal, 3 informational, 4 decisional)."}]},{"text":[{"text":"Katz: technical (first-line), human (all levels), conceptual (top), plus political."}]},{"text":[{"text":"Management is both a science and an art. History: early, classical, behavioural, quantitative, contemporary."}]}]}],"theory":{"itemId":"18575d93-235d-5ae2-971c-dc04634c2596","question":[{"type":"paragraph","text":[{"text":"Define management and explain its four functions."}]}]},"practice":[{"topic":"Managers and Management","named":false}]}},{"kind":"note","itemId":"fd610879-a2a3-5306-b741-a80a83caacdf","sourceKey":"guide-topic:2","position":2,"payload":{"title":"The Management Environment and Integrative Managerial Issues","body":"Environment, culture, global management, social responsibility, ethics, diversity.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"Environment, culture, global management, social responsibility, ethics, diversity."}],"lessons":[{"number":"2.1","title":"How much do managers matter? The external environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Omnipotent view:","bold":true},{"text":" managers "},{"text":"directly responsible","bold":true},{"text":" for success or failure; the "},{"text":"dominant","bold":true},{"text":" view (\"take-charge\" executive; sacked coaches). "},{"text":"Symbolic view:","bold":true},{"text":" "},{"text":"external forces","bold":true},{"text":" responsible; managers have "},{"text":"limited","bold":true},{"text":" effect on substa$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 5, $study_guide$ntive outcomes."}]},{"text":[{"text":"Managers are limited by "},{"text":"culture and environment","bold":true},{"text":". "},{"text":"Internal constraints","bold":true},{"text":" exist in "},{"text":"every","bold":true},{"text":" organization (staff resisting an idea). Managers "},{"text":"widen discretion","bold":true},{"text":" by changing/influencing culture and environment."}]},{"text":[{"text":"External environment:","bold":true},{"text":" forces and institutions "},{"text":"outside","bold":true},{"text":" the organization that could potentially affect performance; "},{"text":"uncontrollable","bold":true},{"text":". "},{"text":"Internal:","bold":true},{"text":" employees, culture."}]},{"text":[{"text":"6 components:","bold":true},{"text":" "},{"text":"economic","bold":true},{"text":" (interest rates, inflation, disposable income, stock market, exchange rates); "},{"text":"demographic","bold":true},{"text":" (population characteristics); "},{"text":"technological","bold":true},{"text":" (automation, office systems; changed fastest); "},{"text":"sociocultural","bold":true},{"text":" (values, attitudes, lifestyles, expectations); "},{"text":"political/legal","bold":true},{"text":" (laws, tax, labour and trade rules, stability, government policy); "},{"text":"global","bold":true},{"text":"."}]},{"text":[{"text":"Business environment:","bold":true},{"text":" "},{"text":"internal and external","bold":true},{"text":" factors, including economic, social ("},{"text":"demographics","bold":true},{"text":" is a social factor), political and technological ones; "},{"text":"climate change","bold":true},{"text":" is an environmental factor. "},{"text":"Exchange-rate","bold":true},{"text":" changes affect "},{"text":"international trade","bold":true},{"text":"; a growing economy brings "},{"text":"increased business opportunities","bold":true},{"text":". "},{"text":"Technological innovation by competitors","bold":true},{"text":" is an "},{"text":"external threat","bold":true},{"text":"."}]},{"text":[{"text":"Competitive environment:","bold":true},{"text":" described by "},{"text":"market conditions","bold":true},{"text":"; "},{"text":"market structure","bold":true},{"text":" = "},{"text":"level of competition","bold":true},{"text":". "},{"text":"Free-market economy:","bold":true},{"text":" "},{"text":"consumer choice","bold":true},{"text":", competition, prices set by supply and demand."}]},{"text":[{"text":"Business strategy","bold":true},{"text":" is influenced by "},{"text":"internal resources, economic conditions and technological trends","bold":true},{"text":"; "},{"text":"strategic planning","bold":true},{"text":" = "},{"text":"setting long-term goals","bold":true},{"text":". "},{"text":"Business growth","bold":true},{"text":" is affected by "},{"text":"market demand, political stability and economic policies","bold":true},{"text":". A business's "},{"text":"primary objective","bold":true},{"text":" is to "},{"text":"generate profits","bold":true},{"text":"; "},{"text":"business policies","bold":true},{"text":" "},{"text":"regulate internal operations","bold":true},{"text":"."}]},{"text":[{"text":"Specific (micro):","bold":true},{"text":" direct, immediate impact; unique, changing with conditions: "},{"text":"customers, suppliers, competitors, pressure groups","bold":true},{"text":". Government policy is "},{"text":"not","bold":true},{"text":" micro."}]},{"text":[{"text":"General (macro):","bold":true},{"text":" the 6 components; "},{"text":"smaller","bold":true},{"text":" effect than specific. Industry conditions are "},{"text":"not","bold":true},{"text":" part of it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Suppliers:","bold":true},{"text":" materials, equipment, capital, labour (lending bank, nurses' union, local labour market); managers want steady inputs at "},{"text":"lowest price","bold":true},{"text":". "},{"text":"Competitors","bold":true},{"text":" include substitutes (courier vs postal service; video recorder vs TV network). "},{"text":"Pressure group:","bold":true},{"text":" consumer group seeking safety laws. The "},{"text":"Internet","bold":true},{"text":" removed geographic boundaries between competitors."}]},{"text":[{"text":"Disability law = "},{"text":"political/legal","bold":true},{"text":"; falling charity donations = "},{"text":"economic","bold":true},{"text":". "},{"text":"Baby Boomers","bold":true},{"text":" born 1946–1964; "},{"text":"Gen Y","bold":true},{"text":" thinks, learns, shops in new ways. 2008 recession: "},{"text":"homeowners unable to pay mortgages","bold":true},{"text":"; "},{"text":"low","bold":true},{"text":" interest rates left firms leveraged."}]},{"text":[{"text":"SWOT:","bold":true},{"text":" Strengths, Weaknesses, Opportunities, Threats. "},{"text":"Oligopoly","bold":true},{"text":" = few sellers. Inflation raises costs; "},{"text":"Central Bank","bold":true},{"text":" regulates. Firms influence environment by "},{"text":"lobbying","bold":true},{"text":", adapt by "},{"text":"restructuring","bold":true},{"text":"."}]}]}]},{"number":"2.2","title":"How the environment affects managers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 effects: (1) jobs and employment, (2) "},{"text":"environmental uncertainty","bold":true},{"text":", (3) stakeholder relationships."}]},{"text":[{"text":"Uncertainty:","bold":true},{"text":" 2 dimensions, "},{"text":"change","bold":true},{"text":" (frequent = "},{"text":"dynamic","bold":true},{"text":", minimal = "},{"text":"stable","bold":true},{"text":") and "},{"text":"complexity","bold":true},{"text":" ("},{"text":"number of components","bold":true},{"text":", "},{"text":"knowledge","bold":true},{"text":" of them). Managers keep it "},{"text":"as low as possible","bold":true},{"text":"."}]},{"text":[{"text":"Stakeholders:","bold":true},{"text":" groups "},{"text":"affected by","bold":true},{"text":" the organization's decisions and actions (investors, empl$study_guide$);
