insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 9, $study_guide$e69c","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Foundations of Decision Making and Foundations of Planning","body":"The 8-step decision process, decision types and conditions, group decisions; planning, the 6-step strategic process, strategies, goals, MBO and planning tools.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The 8-step decision process, decision types and conditions, group decisions; planning, the 6-step strategic process, strategies, goals, MBO and planning tools."}],"lessons":[{"number":"3.1","title":"The decision-making process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Decision making:","bold":true},{"text":" choosing among alternatives (the best course of action); closely linked with "},{"text":"planning","bold":true},{"text":"; its primary goal is to "},{"text":"resolve organizational issues efficiently","bold":true},{"text":". It does not by itself lead to performance monitoring or industrial harmony. "},{"text":"Problem:","bold":true},{"text":" a gap between existing and desired states."}]},{"text":[{"text":"8 steps:","bold":true},{"text":" 1 identify a problem; 2 identify decision criteria; 3 allocate weights to criteria; 4 develop alternatives ("},{"text":"consider all alternatives","bold":true},{"text":"); 5 analyse alternatives; 6 select one; 7 implement it; 8 evaluate its effectiveness. "},{"text":"Ignoring team feedback","bold":true},{"text":" is not a step; corrective action follows evaluation."}]},{"text":[{"text":"Criteria:","bold":true},{"text":" factors relevant to solving the problem. "},{"text":"Heuristics:","bold":true},{"text":" rules of thumb."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Step 1:","bold":true},{"text":" "},{"text":"pressure to act","bold":true},{"text":" must exist first."}]},{"text":[{"text":"Step 3:","bold":true},{"text":" score the most important criterion (10), weight the others against it; if all are equal, weighting is not needed."}]},{"text":[{"text":"Steps 5-6:","bold":true},{"text":" appraise alternatives against the "},{"text":"criteria","bold":true},{"text":"; pick the "},{"text":"highest score","bold":true},{"text":"."}]},{"text":[{"text":"Step 7:","bold":true},{"text":" letting those affected "},{"text":"take part","bold":true},{"text":" raises commitment. "},{"text":"Step 8:","bold":true},{"text":" final; reviewing outcomes and "},{"text":"feedback","bold":true},{"text":" "},{"text":"evaluate effectiveness","bold":true},{"text":" and "},{"text":"identify areas for improvement","bold":true},{"text":"; you may "},{"text":"restart","bold":true},{"text":"."}]},{"text":[{"text":"Confirmation bias","bold":true},{"text":" is the "},{"text":"most common","bold":true},{"text":" bias. "},{"text":"Sunk costs","bold":true},{"text":" are "},{"text":"irrelevant","bold":true},{"text":" to future decisions. Bias is reduced by "},{"text":"seeking expert advice","bold":true},{"text":"."}]},{"text":[{"text":"An effective decision is "},{"text":"rational","bold":true},{"text":"; its key feature is "},{"text":"careful analysis of alternatives","bold":true},{"text":"; makers are "},{"text":"proactive and analytical","bold":true},{"text":". The decision-making process ensures "},{"text":"efficient use of resources","bold":true},{"text":". Under uncertainty, be "},{"text":"flexible and adaptive","bold":true},{"text":"."}]},{"text":[{"text":"Time pressure","bold":true},{"text":" hinders decisions; quick ones are "},{"text":"not always optimal","bold":true},{"text":". "},{"text":"Experience, complexity and time constraints","bold":true},{"text":" all influence decision-making speed; risk and certainty also matter."}]}]}]},{"number":"3.2","title":"Approaches, types of decisions and conditions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rational:","bold":true},{"text":" consistent choices that "},{"text":"maximise value","bold":true},{"text":" within limits; a perfectly rational maker is "},{"text":"objective and logical","bold":true},{"text":"; the model assumes "},{"text":"complete information","bold":true},{"text":" and logical evaluation (bounded rationality has limited information)."}]},{"text":[{"text":"Bounded rationality:","bold":true},{"text":" rational "},{"text":"within limits","bold":true},{"text":" of information and resources; "},{"text":"simplified models","bold":true},{"text":"; "},{"text":"satisfice","bold":true},{"text":" = accept \"good enough\". Perfect rationality gives a "},{"text":"maximising","bold":true},{"text":" choice; bounded gives a "},{"text":"satisficing","bold":true},{"text":" one."}]},{"text":[{"text":"Intuition:","bold":true},{"text":" experience, feelings, accumulated judgement (\"gut feeling\"); research finds managers use information from the "},{"text":"subconscious","bold":true},{"text":" to help them decide."}]},{"text":[{"text":"Escalation of commitment:","bold":true},{"text":" more commitment to an earlier decision despite evidence it was wrong."}]},{"text":[{"text":"Structured problem:","bold":true},{"text":" familiar, easily defined (equipment breakdown). Needs a "},{"text":"programmed","bold":true},{"text":" decision: routine, repetitive, uses past solutions (daily office hours); lower-level managers. Problem, decision and level link up: "},{"text":"integration","bold":true},{"text":". It "},{"text":"improves organizational efficiency","bold":true},{"text":" and cuts the need for costly managerial talent; a local fast-food manager makes the most."}]},{"text":[{"text":"Unstructured problem:","bold":true},{"text":" new, unusual, ambiguous or incomplete information. Needs a "},{"text":"nonprogrammed","bold":true},{"text":" decision: unique, nonrecurring, custom-made, usually under "},{"text":"uncertainty","bold":true},{"text":"; upper-level managers."}]},{"text":[{"text":"3 ways to make programmed decisions:","bold":true},{"text":" "},{"text":"procedure","bold":true},{"text":" (related, se$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 10, $study_guide$quential steps); "},{"text":"rule","bold":true},{"text":" (explicit statement of what may or may not be done); "},{"text":"policy","bold":true},{"text":" (guideline that "},{"text":"sets parameters","bold":true},{"text":", with an "},{"text":"ambiguous term","bold":true},{"text":", e.g. \"productive relationships with organizations in its community\")."}]},{"text":[{"text":"3 conditions:","bold":true},{"text":" "},{"text":"certainty","bold":true},{"text":" (every outcome known, e.g. three dealers' prices); "},{"text":"risk","bold":true},{"text":" (probabilities estimable, e.g. a Lagos shop using last rainy season's sales); "},{"text":"uncertainty","bold":true},{"text":" (neither: the outcome is "},{"text":"unpredictable","bold":true},{"text":", with outcomes unknown and risk not measurable)."}]},{"text":[{"text":"Under uncertainty:","bold":true},{"text":" "},{"text":"maximax","bold":true},{"text":" = maximise the maximum payoff (all on the long shot), optimist; "},{"text":"maximin","bold":true},{"text":" = maximise the minimum payoff, pessimist; "},{"text":"minimax","bold":true},{"text":" = minimise the maximum \"regret\"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rationality assumes","bold":true},{"text":" a clear problem, single goal, "},{"text":"constant, stable","bold":true},{"text":" preferences (\"preferences keep changing\" is not one), best "},{"text":"economic","bold":true},{"text":" interests; it is possible when problems are simple, goals clear, alternatives few. Culture, politics and power also shape decisions."}]},{"text":[{"text":"Intuition's aspects:","bold":true},{"text":" experience, feelings, cognitive skills, subconscious processing, values; never programmed decisions."}]},{"text":[{"text":"Styles:","bold":true},{"text":" directive, analytic, conceptual, behavioural."}]},{"text":[{"text":"Levels:","bold":true},{"text":" "},{"text":"strategic","bold":true},{"text":" (top; long-term); "},{"text":"tactical","bold":true},{"text":" (middle; "},{"text":"medium-term","bold":true},{"text":", turns strategy into specific actions; if \"medium-term\" is absent, choose \"short-term goals\"); "},{"text":"operational","bold":true},{"text":" (first-line; "},{"text":"day-to-day operations and specific tasks","bold":true},{"text":", routine)."}]},{"text":[{"text":"Centralised:","bold":true},{"text":" authority at the top. "},{"text":"Decentralised:","bold":true},{"text":" delegated downward."}]}]}]},{"number":"3.3","title":"Group decisions and decision tools","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Group","bold":true},{"text":" style = "},{"text":"collaboration and consensus","bold":true},{"text":"."}]},{"text":[{"text":"Benefits:","bold":true},{"text":" more information and alternatives, greater acceptance and legitimacy. "},{"text":"Drawbacks:","bold":true},{"text":" time-consuming, minority domination, "},{"text":"groupthink","bold":true},{"text":", ambiguous responsibility."}]},{"text":[{"text":"Groupthink:","bold":true},{"text":" overemphasis on consensus; members hold back different views."}]},{"text":[{"text":"3 ways to boost creativity:","bold":true},{"text":" 1 "},{"text":"brainstorming","bold":true},{"text":" (many ideas, criticism withheld); 2 "},{"text":"nominal group technique","bold":true},{"text":" (members write ideas independently; discussion restricted); 3 "},{"text":"electronic meetings","bold":true},{"text":" (interaction by computer)."}]},{"text":[{"text":"National culture","bold":true},{"text":" affects decisions and risk taking."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Vroom-Yetton:","bold":true},{"text":" subordinates' "},{"text":"participation","bold":true},{"text":". "},{"text":"Delphi:","bold":true},{"text":" "},{"text":"expert opinions","bold":true},{"text":". "},{"text":"Decision tree:","bold":true},{"text":" evaluates choices systematically."}]},{"text":[{"text":"Cost-benefit analysis:","bold":true},{"text":" pros and cons. "},{"text":"SWOT:","bold":true},{"text":" "},{"text":"qualitative","bold":true},{"text":". "},{"text":"Scenario analysis:","bold":true},{"text":" future possibilities. "},{"text":"PERT:","bold":true},{"text":" project duration."}]},{"text":[{"text":"Opportunity cost:","bold":true},{"text":" best alternative foregone. "},{"text":"Risk tolerance:","bold":true},{"text":" willingness to take risks. "},{"text":"Risk management:","bold":true},{"text":" assessing potential losses. "},{"text":"Ethical decisions:","bold":true},{"text":" morality, fairness; a step in ethical decision-making is "},{"text":"identifying stakeholders","bold":true},{"text":". "},{"text":"Participative decision-making:","bold":true},{"text":" its key element is "},{"text":"employee involvement","bold":true},{"text":"."}]}]}]},{"number":"3.4","title":"Planning, strategic management and strategies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Planning:","bold":true},{"text":" making goals, policies and procedures: defining goals, setting an overall strategy, developing comprehensive plans "},{"text":"to integrate and coordinate","bold":true},{"text":" work. Deciding in advance what, how, when, by whom. Key elements: "},{"text":"goals","bold":true},{"text":", "},{"text":"plans","bold":true},{"text":". It includes "},{"text":"developing and selecting a course of action","bold":true},{"text":" and "},{"text":"decision-making","bold":true},{"text":", never creating problems. Success of a plan depends on "},{"text":"proper planning and execution","bold":true},{"text":"."}]},{"text":[{"text":"It is the "},{"text":"first (primary)","bold":true},{"text":" function, the foundation of the others, at "},{"text":"all levels","bold":true},{"text":". Organizing is to structure as planning is to "},{"text":"goal setting","bold":true},{"text":". Its first step is "},{"text":"setting objectives","bold":true},{"text":"; begin by working out how to satisfy cus$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 11, $study_guide$tomer needs."}]},{"text":[{"text":"Formal planning:","bold":true},{"text":" specific goals over years, "},{"text":"written","bold":true},{"text":", shared. "},{"text":"Informal:","bold":true},{"text":" general, lacks continuity, unwritten, little sharing."}]},{"text":[{"text":"4 reasons for planning:","bold":true},{"text":" direction; less impact of change; less waste and redundancy; sets control standards."}]},{"text":[{"text":"Criticisms:","bold":true},{"text":" rigidity; replaces intuition; focus on today's competition; reinforces success; a "},{"text":"dynamic environment","bold":true},{"text":" cannot be planned for. Regulations, unions and other environmental forces limit options and "},{"text":"reduce the impact of planning","bold":true},{"text":" on performance."}]},{"text":[{"text":"Strategic management:","bold":true},{"text":" decisions and actions determining "},{"text":"long-run","bold":true},{"text":" performance; uses all management functions; suits all organizations."}]},{"text":[{"text":"6 steps:","bold":true},{"text":" 1 identify "},{"text":"mission, goals, strategies","bold":true},{"text":" (mission = reason for being in business; purpose and direction); 2 "},{"text":"external analysis","bold":true},{"text":" (competitors, laws, labour supply): "},{"text":"opportunities and threats","bold":true},{"text":"; it is finished when managers have an "},{"text":"accurate picture of the external environment","bold":true},{"text":" and are "},{"text":"aware of trends","bold":true},{"text":" that could affect the organization; 3 "},{"text":"internal analysis","bold":true},{"text":": "},{"text":"strengths and weaknesses","bold":true},{"text":"; 4 "},{"text":"formulate","bold":true},{"text":" strategies: develop and evaluate alternatives, choose those that "},{"text":"use strengths and correct weaknesses","bold":true},{"text":"; 5 "},{"text":"implement","bold":true},{"text":"; 6 "},{"text":"evaluate","bold":true},{"text":" (how effective were they?)."}]},{"text":[{"text":"SWOT:","bold":true},{"text":" combined internal and external analysis. "},{"text":"Core competencies:","bold":true},{"text":" major value-creating skills, capabilities, resources, exceptional or unique (e.g. meeting a target market's needs on a large scale; communicating with customers worldwide in their own languages). An organization's "},{"text":"strengths and weaknesses","bold":true},{"text":" play a "},{"text":"key","bold":true},{"text":" role in corporate planning. Strong and weak cultures affect strategy differently, and a culture's "},{"text":"content","bold":true},{"text":" affects which strategies can be pursued; a strong culture is "},{"text":"harder to change","bold":true},{"text":"."}]},{"text":[{"text":"Strategy levels:","bold":true},{"text":" "},{"text":"corporate","bold":true},{"text":" (which businesses, each unit's role); "},{"text":"business/competitive","bold":true},{"text":" (how to compete in each business); "},{"text":"functional","bold":true},{"text":" (supports "},{"text":"business-level","bold":true},{"text":")."}]},{"text":[{"text":"3 corporate strategies:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Growth:","bold":true},{"text":" more markets or products, via concentration, integration, diversification. "},{"text":"Horizontal integration:","bold":true},{"text":" same industry (two airlines merging). "},{"text":"Vertical:","bold":true},{"text":" backward or forward. "},{"text":"Related diversification:","bold":true},{"text":" different but related industries. "},{"text":"Unrelated:","bold":true},{"text":" different, unconnected."}]},{"text":[{"text":"Stability:","bold":true},{"text":" continue as now; fits slow or no growth and industry upheaval."}]},{"text":[{"text":"Renewal:","bold":true},{"text":" addresses decline: "},{"text":"retrenchment","bold":true},{"text":" (deals with weaknesses, stabilises operations, renews resources) and "},{"text":"turnaround","bold":true},{"text":"."}]}]}]},{"text":[{"text":"BCG matrix:","bold":true},{"text":" high growth + high share = "},{"text":"star","bold":true},{"text":"; high growth + low share = "},{"text":"question mark","bold":true},{"text":"; low growth + high share = "},{"text":"cash cow","bold":true},{"text":"; low growth + low share = "},{"text":"dog","bold":true},{"text":" (neither uses nor makes much cash)."}]},{"text":[{"text":"SBUs:","bold":true},{"text":" independent businesses with own strategies, each serving a clearly defined product-market segment. "},{"text":"Competitive advantage:","bold":true},{"text":" a distinct edge; steady quality makes it "},{"text":"sustainable","bold":true},{"text":"."}]},{"text":[{"text":"Porter's 3 strategies:","bold":true},{"text":" "},{"text":"cost leadership","bold":true},{"text":" (lowest cost structure); "},{"text":"differentiation","bold":true},{"text":" (unique in ways customers value, e.g. faster-response systems); "},{"text":"focus","bold":true},{"text":" (advantage in a narrow niche). Some "},{"text":"industries","bold":true},{"text":" are more profitable than others."}]},{"text":[{"text":"Porter's 5 forces:","bold":true},{"text":" "},{"text":"new entrants","bold":true},{"text":" (barriers: economies of scale, brand loyalty); "},{"text":"substitutes","bold":true},{"text":" (switching costs, buyer loyalty); "},{"text":"buyers","bold":true},{"text":"' power; "},{"text":"suppliers","bold":true},{"text":"' power (concentration, substitute inputs); "},{"text":"existing rivalry","bold":true},{"text":" (growth, demand, product differences)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Planning cannot remove change; it makes managers "},{"text":"anticipate","bold":true},{"text":" it and think about its impact. Research on planning is "},{"text":"positive","bold":true},{"text":"; "},{"text":"quality","bold":true},{"text":" and "},{"text":"implementation","bold":true},{"text":" matter more than extent. Where it failed, the $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 12, $study_guide$"},{"text":"external environment","bold":true},{"text":" (regulations, unions) was to blame. Labour supply is "},{"text":"external","bold":true},{"text":"."}]},{"text":[{"text":"Strategic weapons:","bold":true},{"text":" customer service (staff training), employee skills, innovation (first to market = "},{"text":"first mover","bold":true},{"text":"), quality, "},{"text":"benchmarking","bold":true},{"text":". Senior managers choose whether innovation focuses on "},{"text":"basic research, product innovation or process development","bold":true},{"text":" (process development improves existing work processes and makes the firm more efficient). "},{"text":"Rule of three:","bold":true},{"text":" three companies usually hold most of the market; only three full-line generalists."}]}]}]},{"number":"3.5","title":"Goals, plans and planning tools","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"To "},{"text":"fail to plan","bold":true},{"text":" is to "},{"text":"plan to fail","bold":true},{"text":".\" "},{"text":"Who does the planning","bold":true},{"text":" gives the best understanding of how an organization plans. Planning tools and techniques help managers "},{"text":"prepare confidently for the future","bold":true},{"text":"."}]},{"text":[{"text":"Goals (objectives):","bold":true},{"text":" desired outcomes; same meaning; the "},{"text":"foundation of planning","bold":true},{"text":", they give direction and are the "},{"text":"standard against which actual results are measured","bold":true},{"text":". "},{"text":"Plans:","bold":true},{"text":" resource allocations, schedules, actions to meet goals."}]},{"text":[{"text":"2 goal types:","bold":true},{"text":" financial and strategic. "},{"text":"Stated goals:","bold":true},{"text":" what the organization wants stakeholders to believe; they seem to conflict because different groups (stockholders, customers, employees, the public) are given "},{"text":"different objectives","bold":true},{"text":". "},{"text":"Real goals:","bold":true},{"text":" what members do."}]},{"text":[{"text":"Traditional goal setting:","bold":true},{"text":" top managers set goals, split into subgoals; they grow "},{"text":"less clear and unified","bold":true},{"text":" downward. Each level works toward the goals "},{"text":"assigned to its own area of responsibility","bold":true},{"text":". Clear hierarchy = "},{"text":"means-ends chain","bold":true},{"text":"."}]},{"text":[{"text":"MBO","bold":true},{"text":" ("},{"text":"Peter Drucker","bold":true},{"text":"): goals "},{"text":"jointly","bold":true},{"text":" set, "},{"text":"progress reviewed periodically","bold":true},{"text":", rewards by progress. It "},{"text":"increases","bold":true},{"text":" performance. Weaknesses: poor in changing environments, individual focus, not taken seriously."}]},{"text":[{"text":"Well-written goals:","bold":true},{"text":" outcomes not actions; measurable; timed; challenging but attainable; written; communicated. A "},{"text":"single goal","bold":true},{"text":" tempts unethical behaviour because managers "},{"text":"neglect other important parts of their job just to look good on that one measure","bold":true},{"text":"; no single measure shows success."}]},{"text":[{"text":"Plans by breadth:","bold":true},{"text":" "},{"text":"strategic","bold":true},{"text":" (whole organization, overall goals, positions it in its environment, longer, broader) vs "},{"text":"operational","bold":true},{"text":" (how to achieve goals; lower levels; concerned with "},{"text":"day-to-day operations and specific tasks","bold":true},{"text":")."}]},{"text":[{"text":"By time frame:","bold":true},{"text":" "},{"text":"long-term","bold":true},{"text":" (over 3 years) vs "},{"text":"short-term","bold":true},{"text":" (1 year or less)."}]},{"text":[{"text":"By specificity:","bold":true},{"text":" "},{"text":"specific","bold":true},{"text":" (no room for interpretation, e.g. 2.45 per cent tobacco tax rise over 2 years) vs "},{"text":"directional","bold":true},{"text":" (flexible guidelines; flexibility costs the "},{"text":"clarity","bold":true},{"text":" specific plans provide)."}]},{"text":[{"text":"By frequency of use:","bold":true},{"text":" "},{"text":"single-use","bold":true},{"text":" (unique situation) vs "},{"text":"standing","bold":true},{"text":" (repeated activities, e.g. skateboarding policy)."}]},{"text":[{"text":"3 contingency factors:","bold":true},{"text":" organizational level, environmental uncertainty, length of future commitments ("},{"text":"commitment concept","bold":true},{"text":": plans reach far enough to meet commitments made)."}]},{"text":[{"text":"2 approaches:","bold":true},{"text":" "},{"text":"traditional","bold":true},{"text":" (top managers, helped by planning specialists) and "},{"text":"members take part","bold":true},{"text":" (plans become more than paper)."}]},{"text":[{"text":"Uncertain environments:","bold":true},{"text":" keep formal planning; plans "},{"text":"specific but flexible","bold":true},{"text":"; planning "},{"text":"ongoing","bold":true},{"text":"; \"long term\" has changed. Pushing planning down "},{"text":"flattens","bold":true},{"text":" hierarchy. Issues are "},{"text":"not equally important","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Explain more: planning tools","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Budget:","bold":true},{"text":" numerical plan allocating resources to specific activities (even space); popular as it applies to many kinds of organizations and to "},{"text":"work activities within organizations","bold":true},{"text":"; brings financial discipline across the organization. Many managers dislike preparing budgets, seeing the process as "},{"text":"time-consuming, inflexible, inefficient and ineffective","bold":true},{"text":"."}]},{"text":[{"text":"Gantt chart:","bold":true},{"text":" "},{"text":"Henry Gantt","bold":true},{"text":" (associate of "},{"text":"F$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 13, $study_guide$rederick Taylor","bold":true},{"text":"), for "},{"text":"scheduling","bold":true},{"text":"; "},{"text":"time horizontal","bold":true},{"text":", activities vertical; compares plan with "},{"text":"actual progress","bold":true},{"text":". "},{"text":"Load chart:","bold":true},{"text":" vertical axis lists departments or "},{"text":"specific resources","bold":true},{"text":"."}]},{"text":[{"text":"PERT:","bold":true},{"text":" schedules "},{"text":"projects","bold":true},{"text":"; activity order and time or costs. "},{"text":"Events:","bold":true},{"text":" end points marking completion of major activities. "},{"text":"Activities:","bold":true},{"text":" time or resources between events. "},{"text":"Slack time:","bold":true},{"text":" possible delay without delaying the project. "},{"text":"Critical path:","bold":true},{"text":" longest sequence."}]},{"text":[{"text":"Break-even analysis:","bold":true},{"text":" "},{"text":"profit projections","bold":true},{"text":" (e.g. an Ikeja store's jacket target); total revenue = "},{"text":"total cost","bold":true},{"text":". Needs price, variable cost per unit, "},{"text":"total fixed costs","bold":true},{"text":". Property taxes are fixed."}]},{"text":[{"text":"Linear programming:","bold":true},{"text":" needs limited resources and an outcome to optimise, so not every allocation problem; applications include choosing "},{"text":"transport routes","bold":true},{"text":" that minimise shipping costs, "},{"text":"sharing an advertising budget","bold":true},{"text":" among plans and "},{"text":"assigning personnel","bold":true},{"text":" to projects; a change in one variable gives an "},{"text":"exactly proportional","bold":true},{"text":" change in the other."}]},{"text":[{"text":"Project management:","bold":true},{"text":" completing a "},{"text":"project","bold":true},{"text":" (one-time, definite start and end) on time, within budget, to specification. "},{"text":"Identify","bold":true},{"text":" activities and resources first. Members stay in permanent work areas, so influence is "},{"text":"communication and persuasion","bold":true},{"text":"."}]},{"text":[{"text":"Scenario (contingency) planning:","bold":true},{"text":" alternative courses for unexpected events; reduces uncertainty by playing out situations; different assumptions give different outcomes; hard for "},{"text":"random events","bold":true},{"text":". Tools never replace managers' "},{"text":"skills and capabilities","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Decision = choice among alternatives; problem = gap; 8 steps."}]},{"text":[{"text":"Rational maximises; bounded satisfices."}]},{"text":[{"text":"Programmed = structured; nonprogrammed = unstructured, uncertainty."}]},{"text":[{"text":"Maximax optimist, maximin pessimist, minimax regret."}]},{"text":[{"text":"Planning = goals and plans; 6 strategic steps."}]},{"text":[{"text":"Growth, stability, renewal; cost leadership, differentiation, focus."}]}]}],"theory":{"itemId":"b1536dbc-f454-5dad-8fa7-0dae17d04b05","question":[{"type":"paragraph","text":[{"text":"Explain the steps in the strategic management process. Distinguish between growth, stability and renewal strategies."}]}]},"practice":[{"topic":"Foundations of Decision Making and Planning","named":false}]}},{"kind":"note","itemId":"ee7efb0c-8198-5380-8487-f0053e33961b","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Organization Design and Structure","body":"The six design elements; authority and power; mechanistic vs organic; the four contingency factors; the designs; today's challenges.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The six design elements; authority and power; mechanistic vs organic; the four contingency factors; the designs; today's challenges."}],"lessons":[{"number":"4.1","title":"Organizing, work specialization and departmentalization","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organizing:","bold":true},{"text":" arranging and structuring work to accomplish organizational goals. It "},{"text":"follows planning","bold":true},{"text":". Organizing is to "},{"text":"structure","bold":true},{"text":" as planning is to "},{"text":"goal setting","bold":true},{"text":"."}]},{"text":[{"text":"Structure:","bold":true},{"text":" the formal framework by which job tasks are divided, grouped and coordinated. "},{"text":"Chart:","bold":true},{"text":" its picture. "},{"text":"Design:","bold":true},{"text":" developing or changing it."}]},{"text":[{"text":"6 elements of design:","bold":true},{"text":" work specialization, departmentalization, chain of command, span of control, centralization/decentralization, formalization. Together they decide if a structure is "},{"text":"mechanistic or organic","bold":true},{"text":"."}]},{"text":[{"text":"7 purposes of organizing:","bold":true},{"text":" divide work into jobs and departments; assign tasks and responsibilities; coordinate tasks; cluster jobs into units; establish relationships among individuals, groups, departments; establish formal lines of authority; allocate and deploy resources. (\"It creates services\" is not one.)"}]},{"text":[{"text":"Work specialization (division of labour):","bold":true},{"text":" the degree to which tasks are divided into separate jobs; each employee does "},{"text":"part","bold":true},{"text":" of an activity, not the whole."}]},{"text":[{"text":"Departmentalization:","bold":true},{"text":" the basis on which jobs are grouped to achieve goals. "},{"text":"5 types:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Functional:","bold":true},{"text":" by functions or tasks."}]},{"text":[{"text":"Geographic:","bold":true},{"text":" by territory or location."}]},{"text":[{"text":"Product:","bold":true},{"text":" by product line or service."}]},{"text":[{"text":"Process:","bold":true},{"text":" by product or customer "},{"text":"flow","bold$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 14, $study_guide$":true},{"text":"."}]},{"text":[{"text":"Customer:","bold":true},{"text":" by type of customer and needs. Now more important: tracks customer needs and responds to changes."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Principles:","bold":true},{"text":" "},{"text":"unity of objective","bold":true},{"text":" (the structure must serve the organization's goals); "},{"text":"efficiency","bold":true},{"text":" ("},{"text":"lowest cost, least waste","bold":true},{"text":"); division of work; span of control; "},{"text":"scalar chain","bold":true},{"text":" (line of authority top to bottom); unity of command; "},{"text":"parity of authority and responsibility","bold":true},{"text":" (in balance); "},{"text":"delegation of authority","bold":true},{"text":" (decision power at the proper level); balance, flexibility, continuity. "},{"text":"Publicity","bold":true},{"text":" is not a principle."}]},{"text":[{"text":"Early view: endless source of productivity. Too far: boredom, fatigue, absenteeism, turnover. More tasks per worker "},{"text":"reduces","bold":true},{"text":" it."}]},{"text":[{"text":"Cross-functional team:","bold":true},{"text":" people from different functions."}]}]}]},{"number":"4.2","title":"Chain of command, authority, power and span of control","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Chain of command:","bold":true},{"text":" the unbroken line of authority from top to lowest levels; shows who reports to whom. The formal structure of authority is the "},{"text":"hierarchy","bold":true},{"text":"."}]},{"text":[{"text":"Authority:","bold":true},{"text":" the rights of a position to tell people what to do and expect compliance. "},{"text":"Responsibility:","bold":true},{"text":" obligation to perform a duty."}]},{"text":[{"text":"Unity of command:","bold":true},{"text":" each person reports to "},{"text":"only one","bold":true},{"text":" manager (Fayol; keeps authority continuous)."}]},{"text":[{"text":"Delegation:","bold":true},{"text":" transferring authority to another person for specific duties."}]},{"text":[{"text":"Line authority:","bold":true},{"text":" directs employees' work; follows the chain of command. "},{"text":"Staff authority:","bold":true},{"text":" supports, assists, advises and reduces the load of line managers."}]},{"text":[{"text":"Authority","bold":true},{"text":" is a "},{"text":"right","bold":true},{"text":", from the "},{"text":"position","bold":true},{"text":". "},{"text":"Power","bold":true},{"text":" is a "},{"text":"capacity to influence","bold":true},{"text":" decisions and is the "},{"text":"broader","bold":true},{"text":" concept; authority is part of it."}]},{"text":[{"text":"5 sources of power:","bold":true},{"text":" "},{"text":"legitimate","bold":true},{"text":" (position; same as authority), "},{"text":"coercive","bold":true},{"text":" (ability to punish or control), "},{"text":"reward","bold":true},{"text":" (pay, bonuses, praise), "},{"text":"expert","bold":true},{"text":" (special knowledge), "},{"text":"referent","bold":true},{"text":" (personal traits others admire)."}]},{"text":[{"text":"Span of control:","bold":true},{"text":" the number of employees a manager can efficiently and effectively supervise. It decides the number of management "},{"text":"levels","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Authority stays with the post when holder leaves. Power without authority: a secretary controlling access."}]},{"text":[{"text":"Chain of command matters less today: "},{"text":"information technology and empowered employees","bold":true},{"text":"."}]},{"text":[{"text":"Narrow span = tall. Wide span = flat","bold":true},{"text":" (few levels). Not \"thin\"."}]},{"text":[{"text":"4,096 operatives: span 4 needs "},{"text":"1,365","bold":true},{"text":" managers, "},{"text":"7","bold":true},{"text":" levels (with operatives); span 8 needs "},{"text":"585","bold":true},{"text":", "},{"text":"5","bold":true},{"text":" levels."}]},{"text":[{"text":"Wider span is more "},{"text":"efficient","bold":true},{"text":" (lower cost, faster decisions, better communication). Too wide: effectiveness falls (too little supervision); many people to control is the disadvantage. "},{"text":"Trend:","bold":true},{"text":" wider spans (cut costs, speed decisions, empower staff)."}]},{"text":[{"text":"Wider span when:","bold":true},{"text":" staff well trained; tasks similar and simple; staff close together; standardized procedures; good information system. Not a factor: organization age."}]}]}]},{"number":"4.3","title":"Centralization, formalization, mechanistic vs organic, contingency factors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Centralization:","bold":true},{"text":" decision making concentrated at upper levels. "},{"text":"Decentralization:","bold":true},{"text":" lower-level managers give input or make decisions. "},{"text":"Employee empowerment:","bold":true},{"text":" increasing workers' decision-making discretion."}]},{"text":[{"text":"Formalization:","bold":true},{"text":" the degree to which jobs are standardized and guided by rules and procedures."}]}]},{"type":"table","header":[[{"text":"Mechanistic"}],[{"text":"Organic"}]],"rows":[[[{"text":"Rigid, tightly controlled, efficient"}],[{"text":"Flexible; changes quickly"}]],[[{"text":"Specialized, standardized jobs"}],[{"text":"Cross-functional, cross-hierarchical teams"}]],[[{"text":"Clear chain of command"}],[{"text":"Free flow of information"}]],[[{"text":"Narrow spans"}],[{"text":"Wide spans"}]],[[{"text":"Centralized, high formalization"}],[{"text":"Decentralized, low formalization"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4 contingency factors:","bold":true},{"text":" "},{"text":"strategy, size, technology, environmental uncertainty.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 15, $study_guide$":"Trend:","bold":true},{"text":" decentralization, for flexibility and responsiveness. "},{"text":"Centralize when:","bold":true},{"text":" stable environment; less capable lower managers; large firm; significant decisions; crisis. "},{"text":"Decentralize when:","bold":true},{"text":" uncertain environment; capable managers wanting a say; minor decisions; open culture; geographic spread. Every decision needing the unit head's sign-off = centralized."}]},{"text":[{"text":"Strategy:","bold":true},{"text":" "},{"text":"structure follows strategy.","bold":true},{"text":" 3 focuses: "},{"text":"innovation","bold":true},{"text":" (meaningful, unique new products) = "},{"text":"organic","bold":true},{"text":"; "},{"text":"cost minimization","bold":true},{"text":" = "},{"text":"mechanistic","bold":true},{"text":"; "},{"text":"imitation","bold":true},{"text":" (copying market leaders to cut risk) = a "},{"text":"mix","bold":true},{"text":". Diversification is not one."}]},{"text":[{"text":"Size:","bold":true},{"text":" as an organization takes on more employees its structure becomes more "},{"text":"specialized","bold":true},{"text":" (not informal): more departmentalization, centralization, rules (not decentralization), so more "},{"text":"mechanistic","bold":true},{"text":"."}]},{"text":[{"text":"Technology: Joan Woodward","bold":true},{"text":" studied small manufacturing firms in "},{"text":"southern England","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Unit","bold":true},{"text":" (units or small batches): least complex; organic."}]},{"text":[{"text":"Mass","bold":true},{"text":" ("},{"text":"large-batch","bold":true},{"text":"): moderate; "},{"text":"mechanistic","bold":true},{"text":"."}]},{"text":[{"text":"Process","bold":true},{"text":" (continuous): "},{"text":"most","bold":true},{"text":" complex; organic."}]}]}]},{"text":[{"text":"Environment:","bold":true},{"text":" stable suits mechanistic; dynamic, uncertain suits "},{"text":"organic","bold":true},{"text":". Forces towards organic: global competition, rivals' faster innovation, customers wanting better quality and faster delivery."}]}]}]},{"number":"4.4","title":"Traditional and contemporary designs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traditional","bold":true},{"text":" (more mechanistic): "},{"text":"simple, functional, divisional.","bold":true},{"text":" Structures grow simple, then functional, then divisional, becoming more "},{"text":"specialized","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple:","bold":true},{"text":" low departmentalization, "},{"text":"wide spans","bold":true},{"text":", authority centralized in one person, little formalization. Suits "},{"text":"very small firms with few employees","bold":true},{"text":" (even one selling worldwide). Strength: fast, flexible, cheap. Weakness: relying on one person is risky."}]},{"text":[{"text":"Functional:","bold":true},{"text":" groups similar occupational specialties. Strength: cost savings from specialization. Weakness: functions lose sight of the whole; specialists isolated."}]},{"text":[{"text":"Divisional:","bold":true},{"text":" "},{"text":"autonomous, self-contained","bold":true},{"text":" units linked by a "},{"text":"product or service","bold":true},{"text":". Strength: "},{"text":"focus on results","bold":true},{"text":". Weakness: "},{"text":"duplication","bold":true},{"text":" of activities and resources."}]}]}]},{"text":[{"text":"Contemporary:","bold":true},{"text":" team, matrix, project, boundaryless, learning organization."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Team:","bold":true},{"text":" whole organization of work teams; "},{"text":"empowerment","bold":true},{"text":" most important."}]},{"text":[{"text":"Matrix:","bold":true},{"text":" functional specialists assigned to projects under a "},{"text":"project manager","bold":true},{"text":"; functional plus "},{"text":"product","bold":true},{"text":" departmentalization."}]},{"text":[{"text":"Project:","bold":true},{"text":" employees "},{"text":"continuously","bold":true},{"text":" work on projects; advanced matrix."}]},{"text":[{"text":"Boundaryless:","bold":true},{"text":" not limited by horizontal, vertical or external boundaries."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Team:","bold":true},{"text":" fewer barriers between functions; weakness: "},{"text":"no clear chain of command","bold":true},{"text":"."}]},{"text":[{"text":"Matrix:","bold":true},{"text":" "},{"text":"two bosses","bold":true},{"text":" (functional and project manager), so it "},{"text":"breaks unity of command","bold":true},{"text":". Strength: fluid, flexible. Weaknesses: complex assignments; task and personality conflicts."}]},{"text":[{"text":"Project:","bold":true},{"text":" no formal department to return to between projects."}]},{"text":[{"text":"Boundaries:","bold":true},{"text":" horizontal = between "},{"text":"functions","bold":true},{"text":"; vertical = between "},{"text":"levels","bold":true},{"text":"; external = with customers, suppliers. Cross-level teams and outside agencies remove them; "},{"text":"virtual","bold":true},{"text":" or "},{"text":"network","bold":true},{"text":" designs minimize them."}]},{"text":[{"text":"3 boundaryless forms:","bold":true},{"text":" "},{"text":"virtual","bold":true},{"text":" (small full-time core plus outside specialists hired "},{"text":"temporarily","bold":true},{"text":"); "},{"text":"network","bold":true},{"text":" (small core "},{"text":"outsources","bold":true},{"text":" major functions such as manufacturing, accounting, payroll); "},{"text":"modular","bold":true},{"text":" (suppliers make "},{"text":"components","bold":true},{"text":", the firm assembles)."}]}]}]},{"number":"4.5","title":"Today's design challenges","mustKnow":[{"type":"list","ordered":false,"items$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 16, $study_guide$":[{"text":[{"text":"4 challenges:","bold":true},{"text":" keeping employees connected (linking dispersed or mobile staff through "},{"text":"technology","bold":true},{"text":"); managing global structural issues (understand how "},{"text":"culture shapes structure","bold":true},{"text":"); building a learning organization; designing flexible work arrangements."}]},{"text":[{"text":"Learning organization:","bold":true},{"text":" capacity to continuously learn, adapt and change. Ability to "},{"text":"learn and apply","bold":true},{"text":" may be its only lasting advantage. It needs "},{"text":"information","bold":true},{"text":"."}]},{"text":[{"text":"5 flexible work arrangements:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Telecommuting:","bold":true},{"text":" working from home, linked by technology."}]},{"text":[{"text":"Compressed workweek:","bold":true},{"text":" longer days, fewer days."}]},{"text":[{"text":"Flextime:","bold":true},{"text":" set weekly hours; staff vary start and finish within limits."}]},{"text":[{"text":"Job sharing:","bold":true},{"text":" two or more people split one full-time job."}]},{"text":[{"text":"Contingent workforce:","bold":true},{"text":" temporary, freelance or contract workers, as demand requires."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learning organization features:","bold":true},{"text":" design = boundaryless, teams, empowerment; information shared openly, timely, accurately; leadership = shared vision, collaboration; culture = strong relationships, community, caring, trust. All members help solve work problems."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organizing follows planning; 6 elements; 5 departmentalizations."}]},{"text":[{"text":"Authority = right; power = broader; one boss."}]},{"text":[{"text":"Narrow span = tall; wide = flat, efficient."}]},{"text":[{"text":"Mechanistic = rigid; organic = flexible."}]},{"text":[{"text":"Contingency: strategy, size, technology, environment."}]},{"text":[{"text":"Traditional: simple, functional, divisional."}]}]}],"theory":{"itemId":"829a57bc-6a83-58b7-8f63-2b5338a3a853","question":[{"type":"paragraph","text":[{"text":"Explain the six key elements of organizational design."}]}]},"practice":[{"topic":"Organization Design and Structure","named":false}]}},{"kind":"note","itemId":"81e93b67-fa80-5cc7-86d3-c07a2d7b96b6","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Managing Human Resources","body":"The 8 HRM activities.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The 8 HRM activities."}],"lessons":[{"number":"5.1","title":"Why HRM matters, the HRM process and outside influences","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"HRM:","bold":true},{"text":" getting, training, keeping and rewarding the right people. Old name: "},{"text":"staffing","bold":true},{"text":" (includes appraisal; not budgeting)."}]},{"text":[{"text":"3 reasons HRM matters:","bold":true},{"text":" "},{"text":"competitive advantage","bold":true},{"text":", "},{"text":"strategy","bold":true},{"text":", effect on "},{"text":"performance","bold":true},{"text":"."}]},{"text":[{"text":"High-performance work practices:","bold":true},{"text":" raise individual and organizational performance, e.g. self-managed teams, decentralised decisions, flexible jobs, open communication, performance-based pay, person-job fit."}]},{"text":[{"text":"8 activities, 3 groups:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Identify and select competent employees: HR planning (1), recruitment and decruitment (2), selection (3)."}]},{"text":[{"text":"Give up-to-date skills and knowledge: orientation (4), training (5)."}]},{"text":[{"text":"Retain competent, high-performing employees: performance management (6), compensation and benefits (7), career development (8)."}]}]}]},{"text":[{"text":"External factors:","bold":true},{"text":" labour unions, laws and regulations, demographic trends; the whole process sits inside the external environment."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Labour union:","bold":true},{"text":" represents workers via "},{"text":"collective bargaining","bold":true},{"text":", giving a "},{"text":"collective bargaining agreement","bold":true},{"text":" (pay, hours, conditions)."}]},{"text":[{"text":"Nigeria: "},{"text":"NLC","bold":true},{"text":" (umbrella body of trade unions); "},{"text":"ASUU","bold":true},{"text":" (university academic staff union); "},{"text":"Labour Act","bold":true},{"text":" (law on hiring, pay, dismissal)."}]},{"text":[{"text":"Affirmative action programmes:","bold":true},{"text":" improve protected groups' position (hiring, promotion). "},{"text":"Demographic trends:","bold":true},{"text":" diverse, ageing workforce. "},{"text":"Hugo Munsterberg","bold":true},{"text":", father of industrial psychology: scientific selection."}]}]}]},{"number":"5.2","title":"HR planning, recruitment and decruitment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"HR planning","bold":true},{"text":" ("},{"text":"employment planning","bold":true},{"text":"): right number and kinds of capable people, right places, right times. "},{"text":"2 steps:","bold":true},{"text":" assess current human resources, then meet future needs (from mission, goals, strategy, demand)."}]},{"text":[{"text":"Human resource inventory:","bold":true},{"text":" record of current employees' education, past jobs, languages, skills."}]},{"text":[{"text":"Job analysis","bold":true},{"text":" (first): defines jobs and needed behaviours; produces:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job description:","bold":true},{"text":" written statement of what the job is: what the jobholder does, how, why. The "},{"text":"job","bold":true},{"text":"."}]},{"text":[{"text":"J$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 17, $study_guide$ob specification:","bold":true},{"text":" minimum qualifications (knowledge, skills, attitudes) for the job. The "},{"text":"person","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Recruitment:","bold":true},{"text":" locating, identifying, attracting capable applicants. "},{"text":"Decruitment:","bold":true},{"text":" reducing the workforce."}]},{"text":[{"text":"7 decruitment options:","bold":true},{"text":" "},{"text":"firing","bold":true},{"text":" (permanent, involuntary); "},{"text":"layoffs","bold":true},{"text":" (temporary, involuntary); "},{"text":"attrition","bold":true},{"text":" (not filling jobs left by resignations or retirements, no one forced out); "},{"text":"transfers","bold":true},{"text":" (sideways or downward, usually no cost cut, balance labour inside); "},{"text":"reduced workweeks","bold":true},{"text":" (cutting everyone's weekly hours instead of letting people go); "},{"text":"early retirements","bold":true},{"text":" (incentives for older, senior staff); "},{"text":"job sharing","bold":true},{"text":" (usually two part-timers share one full-time job)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Recruitment sources","bold":true},{"text":" (advantage; disadvantage):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal search: low cost, morale, known candidates; limited supply, no diversity gain."}]},{"text":[{"text":"Employee referrals: staff know the job, stake their name; no diversity gain."}]},{"text":[{"text":"Adverts, internet: many unqualified applicants."}]},{"text":[{"text":"School and college: large pool; mostly entry-level."}]},{"text":[{"text":"Public agencies: low cost; less skilled."}]},{"text":[{"text":"Private agencies (\"headhunters\"): careful screening; costly, little commitment."}]},{"text":[{"text":"Temporary help: short-term needs; expensive."}]}]}]}]}]},{"number":"5.3","title":"Selection","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selection:","bold":true},{"text":" screening applicants to hire the most appropriate; "},{"text":"prediction","bold":true},{"text":"."}]},{"text":[{"text":"4 outcomes:","bold":true},{"text":" two correct decisions (accepting someone who succeeds; rejecting someone who would have failed), two errors. "},{"text":"Accept error:","bold":true},{"text":" hiring someone who performs poorly (costs: training, poor work, firing and rehiring). "},{"text":"Reject error:","bold":true},{"text":" rejecting someone who would have done well (costs: discrimination claims, losing talent to rivals)."}]},{"text":[{"text":"Validity:","bold":true},{"text":" proven relationship between a device and a criterion such as later job performance (predicts). "},{"text":"Reliability:","bold":true},{"text":" measures the same thing "},{"text":"consistently","bold":true},{"text":". Reliable need not be valid."}]},{"text":[{"text":"6 selection devices:","bold":true},{"text":" application forms, written tests, performance-simulation tests, interviews, background investigations, physical examinations."}]},{"text":[{"text":"Realistic job preview (RJP):","bold":true},{"text":" "},{"text":"positive and negative","bold":true},{"text":" information on job and company; raises satisfaction, lowers turnover."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Application forms:","bold":true},{"text":" basic facts; screen out unqualified applicants. "},{"text":"Written tests:","bold":true},{"text":" intelligence, aptitude, personality, integrity."}]},{"text":[{"text":"Performance-simulation tests","bold":true},{"text":" use actual job behaviour. "},{"text":"Work sampling:","bold":true},{"text":" small replica of the job, central tasks performed; routine, standard jobs. "},{"text":"Assessment centres:","bold":true},{"text":" interviews, problem-solving, group exercises, panel-judged; test "},{"text":"managerial potential","bold":true},{"text":"."}]},{"text":[{"text":"Interviews:","bold":true},{"text":" more valid, reliable if "},{"text":"structured","bold":true},{"text":" (same planned questions). "},{"text":"Behavioural interview:","bold":true},{"text":" how candidates handled real past situations."}]},{"text":[{"text":"Background investigations:","bold":true},{"text":" check application facts and references; references have little value (referees say only good things). "},{"text":"Physical examinations:","bold":true},{"text":" jobs with physical demands; sometimes insurance."}]},{"text":[{"text":"Weber: choosing by technical qualifications is "},{"text":"formal selection","bold":true},{"text":"."}]}]}]},{"number":"5.4","title":"Orientation and training","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Orientation:","bold":true},{"text":" introducing new employees to the job and organization; moves them from "},{"text":"outsider to insider","bold":true},{"text":", lowers anxiety, makes early quitting less likely."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Work unit:","bold":true},{"text":" unit goals, how the job adds to them, co-workers."}]},{"text":[{"text":"Organization:","bold":true},{"text":" company goals, history, philosophy, rules, HR policies (pay, overtime, leave, fringe benefits)."}]}]}]},{"text":[{"text":"Training:","bold":true},{"text":" building job skills and knowledge to do jobs better; raises performance."}]},{"text":[{"text":"Training methods, 2 groups:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traditional:","bold":true},{"text":" on-the-job training, job rotation, mentoring and coaching, experiential exercises (role play, simulations), workbooks, manuals, classroom lectures."}]},{"text":[{"text":"Technology-based:","bold":true},{"text":" CDs, DVDs, video and audio recordings, videoconferencing, teleconferencing, e-learning (internet-based)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job rotati$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 18, $study_guide$on:","bold":true},{"text":" sideways moves to learn several jobs. "},{"text":"Mentoring and coaching:","bold":true},{"text":" experienced employee advises a newer one. "},{"text":"General","bold":true},{"text":" training: communication, computer skills, customer service. "},{"text":"Specific:","bold":true},{"text":" safety, leadership, diversity awareness, product knowledge, ethics."}]},{"text":[{"text":"Signs training is needed: falling output, poorer quality, more accidents, new technology. Training fixes lack of "},{"text":"ability","bold":true},{"text":"."}]}]}]},{"number":"5.5","title":"Performance management, pay, retention and careers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Performance management system:","bold":true},{"text":" setting standards and appraising performance for objective HR decisions and records."}]},{"text":[{"text":"7 appraisal methods","bold":true},{"text":" (advantage; disadvantage):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Written essay:","bold":true},{"text":" writes strengths, weaknesses, past performance, potential; reflects writer's skill."}]},{"text":[{"text":"Critical incidents:","bold":true},{"text":" records behaviours separating effective from ineffective work; rich examples; slow, no numbers."}]},{"text":[{"text":"Graphic rating scales:","bold":true},{"text":" rates factors on a 1 to 5 scale; quick, numbers; little depth."}]},{"text":[{"text":"BARS:","bold":true},{"text":" rates specific job behaviours, "},{"text":"combining critical incidents and graphic rating scales","bold":true},{"text":"; slow, hard to build."}]},{"text":[{"text":"Multiperson comparisons:","bold":true},{"text":" compare one person with others; hard with many, legal concerns."}]},{"text":[{"text":"MBO:","bold":true},{"text":" judged on achieving agreed goals; slow."}]},{"text":[{"text":"360-degree:","bold":true},{"text":" feedback from supervisors, co-workers, subordinates, customers, self; slow."}]}]}]},{"text":[{"text":"3 multiperson comparisons:","bold":true},{"text":" "},{"text":"group order ranking","bold":true},{"text":" (top fifth etc.); "},{"text":"individual ranking","bold":true},{"text":" (best to worst); "},{"text":"paired comparison","bold":true},{"text":" (each against every other). These are "},{"text":"relative","bold":true},{"text":"; other methods are "},{"text":"absolute","bold":true},{"text":"."}]},{"text":[{"text":"Skill-based pay:","bold":true},{"text":" rewards demonstrable skills. "},{"text":"Variable pay:","bold":true},{"text":" pay depends on performance."}]},{"text":[{"text":"Compensation:","bold":true},{"text":" base pay, incentives, "},{"text":"benefits","bold":true},{"text":" (nonwage extras: health care, pensions, leave)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Discipline:","bold":true},{"text":" actions to enforce standards and rules. "},{"text":"Employee counselling:","bold":true},{"text":" helps employees overcome performance problems. Cannot do it: train or coach. Will not: discipline or counsel."}]},{"text":[{"text":"Pay-level factors:","bold":true},{"text":" tenure, performance, kind of job, kind of business, unionised or not, labour- or capital-intensive, management's pay philosophy, location, profitability, size."}]},{"text":[{"text":"Retention:","bold":true},{"text":" keeping satisfied employees (fair pay, benefits, recognition, development). "},{"text":"Career:","bold":true},{"text":" sequence of positions over a lifetime. "},{"text":"Career development:","bold":true},{"text":" helps employees plan and grow careers in the organization."}]}]}]},{"number":"5.6","title":"Current HRM issues","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Downsizing:","bold":true},{"text":" planned elimination of jobs."}]},{"text":[{"text":"Layoff-survivor sickness:","bold":true},{"text":" attitudes, perceptions, behaviours of employees who "},{"text":"remain","bold":true},{"text":" after involuntary cuts (insecurity, unfairness, guilt, stress, lower motivation)."}]},{"text":[{"text":"Sexual harassment:","bold":true},{"text":" unwanted action or activity of a sexual nature that explicitly or implicitly affects employment, performance or work environment. "},{"text":"Quid pro quo:","bold":true},{"text":" job benefit tied to sexual favours. "},{"text":"Hostile environment:","bold":true},{"text":" conduct makes the workplace offensive or intimidating, no job benefit. From a manager or co-worker, against men or women."}]},{"text":[{"text":"Workplace spirituality:","bold":true},{"text":" culture whose values promote purpose through meaningful work in the context of community; not organized religion."}]},{"text":[{"text":"5 features of a spiritual organization:","bold":true},{"text":" strong sense of purpose, focus on individual development, trust and openness, employee empowerment, toleration of employee expression."}]},{"text":[{"text":"HR costs to control:","bold":true},{"text":" "},{"text":"health care","bold":true},{"text":" (wellness programmes, healthy-habit rewards) and "},{"text":"pensions","bold":true},{"text":" (reduce or redesign plans)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Downsizing:","bold":true},{"text":" give leavers notice, severance pay, outplacement. Survivors: let them talk, explain reasons."}]},{"text":[{"text":"Preventing harassment:","bold":true},{"text":" written policy, training, safe reporting, prompt investigation. "},{"text":"Managing diversity:","bold":true},{"text":" wider recruiting net, bias-free selection, diversity training."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"8 activities, 3 groups."}]},{"text":[{"text":"Job description = job; specification = person."}]},{"text":[{"text":"Firing permanent, layoff temporary."}]},{"text":[{"text":"Validity predicts; reliability is consistent."}]},{"text":[{"text":"BARS = critical incidents $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 19, $study_guide$+ graphic rating scales."}]},{"text":[{"text":"Skill-based pay: skills; variable: performance."}]}]}],"theory":{"itemId":"07639d6e-7ae4-5601-b110-361c95df96aa","question":[{"type":"paragraph","text":[{"text":"Explain the HRM process and describe four methods of appraising performance."}]}]},"practice":[{"topic":"Managing Human Resources","named":false}]}},{"kind":"note","itemId":"147675a1-c1bd-5b7e-8be4-0a37e4ef4372","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Managing Change and Innovation","body":"Forces and agents of change, Lewin, OD, resistance, stress, innovation.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"Forces and agents of change, Lewin, OD, resistance, stress, innovation."}],"lessons":[{"number":"6.1","title":"Change, its forces and its agents","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organizational change:","bold":true},{"text":" any alteration of people, structure or technology in an organization."}]},{"text":[{"text":"Change agent:","bold":true},{"text":" a person who acts as a catalyst and takes responsibility for managing the change process."}]},{"text":[{"text":"External forces (5):","bold":true},{"text":" 1. marketplace (competition: rival firms and their new products or prices); 2. government laws and regulations; 3. technology; 4. labour markets; 5. economic changes (interest rates, inflation, recession)."}]},{"text":[{"text":"Internal forces (4):","bold":true},{"text":" 1. changes in organizational strategy; 2. changes in the workforce (age, education, gender, nationality); 3. new equipment; 4. changes in employee attitudes."}]}]},{"type":"table","header":[[{"text":"Change agent"}],[{"text":"Strength"}],[{"text":"Weakness"}]],"rows":[[[{"text":"Internal manager","bold":true}],[{"text":"Knows the organization; more thoughtful as he or she lives with the results"}],[{"text":"May be overcautious"}]],[[{"text":"Outside consultant","bold":true}],[{"text":"Objective view that insiders lack"}],[{"text":"Knows little of the organization's history, culture, procedures and people; may push more drastic change (does not live with the results)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sorting: laws, a skilled-labour shortage = external. A new market = strategy; new machines = equipment (internal)."}]},{"text":[{"text":"Change agents: managers, nonmanagers (e.g. HR change specialists) or outside consultants; large changes often use consultants."}]}]}]},{"number":"6.2","title":"How change happens, types of change and OD","mustKnow":[{"type":"paragraph","text":[{"text":"2 views of change:","bold":true}]},{"type":"table","header":[[],[{"text":"Calm waters"}],[{"text":"White-water rapids"}]],"rows":[[[{"text":"Picture"}],[{"text":"Large ship on a calm sea, storm now and then"}],[{"text":"Small raft on constant, rough rapids"}]],[[{"text":"Change is"}],[{"text":"An occasional break in stable life; fits "},{"text":"Lewin's 3 steps","bold":true}],[{"text":"Natural and constant; constant uncertainty and adjustment"}]],[[{"text":"Managing it"}],[{"text":"Done once, then things settle"}],[{"text":"A continual process"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lewin's 3 steps, in order:","bold":true},{"text":" 1. "},{"text":"unfreezing","bold":true},{"text":" the status quo; 2. "},{"text":"changing","bold":true},{"text":" to a new state; 3. "},{"text":"refreezing","bold":true},{"text":" to make the change permanent."}]},{"text":[{"text":"Status quo:","bold":true},{"text":" an equilibrium state. "},{"text":"Driving forces","bold":true},{"text":" push behaviour away from it; "},{"text":"restraining forces","bold":true},{"text":" hold back movement away from it."}]},{"text":[{"text":"3 ways to unfreeze:","bold":true},{"text":" increase driving forces; decrease restraining forces; combine both."}]},{"text":[{"text":"3 types of change:","bold":true},{"text":" "},{"text":"structure","bold":true},{"text":" (elements: authority relationships, coordinating mechanisms, job design, span of control, formalization, departmentalization; e.g. merging departments, wider spans of control, cutting layers; attitudes and perceptions are NOT structure but people change); "},{"text":"technology","bold":true},{"text":" (equipment, tools, work processes; e.g. automation, computerization, new machines; "},{"text":"automation","bold":true},{"text":" replaces certain tasks done by people with machines); "},{"text":"people","bold":true},{"text":" (attitudes, expectations, perceptions, behaviour; e.g. training, team building, OD)."}]},{"text":[{"text":"Organizational development (OD):","bold":true},{"text":" techniques or programmes to change people and the nature and quality of interpersonal work relationships. It is the main tool for people change."}]},{"text":[{"text":"4 OD techniques:","bold":true}]}]},{"type":"table","header":[[{"text":"Technique"}],[{"text":"What it does"}]],"rows":[[[{"text":"Survey feedback","bold":true}],[{"text":"Questionnaire assesses attitudes and perceptions about the change; results used to spot and solve problems"}]],[[{"text":"Process consultation","bold":true}],[{"text":"Outside consultant helps managers see how interpersonal processes affect the way work is done"}]],[[{"text":"Team building","bold":true}],[{"text":"Helps a work group set goals, build good relationships, clarify each member's role and responsibilities"}]],[[{"text":"Intergroup development","bold":true}],[{"text":"Changes the attitudes, stereotypes and perceptions work groups hold about each other"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lewin treats change as a "},{"text":"break","bold":true},{"text":" in equilibrium. Refreezing stabilises the new situation so it is not short-lived: balance the forces again, e.g. reward the new behaviour."}]},{"text":[{"text":"White-water fits today's uncertain environments (a course whose timetable keeps changing)."}]},{"text":[$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 20, $study_guide${"text":"Team building is "},{"text":"within","bold":true},{"text":" one group; intergroup development is "},{"text":"between","bold":true},{"text":" groups."}]}]}]},{"number":"6.3","title":"Resistance to change and how to reduce it","mustKnow":[{"type":"paragraph","text":[{"text":"4 reasons for resistance:","bold":true},{"text":" 1. "},{"text":"uncertainty","bold":true},{"text":" (known replaced by unknown); 2. "},{"text":"habit","bold":true},{"text":" (preferring routine); 3. "},{"text":"concern over personal loss","bold":true},{"text":" (status, money, authority, friendships); 4. "},{"text":"belief that the change is not in the organization's best interest","bold":true},{"text":"."}]},{"type":"paragraph","text":[{"text":"6 techniques to reduce resistance:","bold":true}]},{"type":"table","header":[[{"text":"Technique"}],[{"text":"Use when"}],[{"text":"Advantage"}],[{"text":"Drawback"}]],"rows":[[[{"text":"Education and communication","bold":true},{"text":" (memos, meetings)"}],[{"text":"Misinformation"}],[{"text":"Clears up misunderstandings"}],[{"text":"May not work when trust and credibility are lacking"}]],[[{"text":"Participation","bold":true},{"text":" (involve those affected in the decision)"}],[{"text":"Resisters have expertise"}],[{"text":"Raises involvement and acceptance"}],[{"text":"Takes time; may give a poor solution"}]],[[{"text":"Facilitation and support","bold":true},{"text":" (counselling, training, paid leave)"}],[{"text":"Resisters are fearful and anxious"}],[{"text":"Helps people adjust"}],[{"text":"Can be expensive; no guarantee of success"}]],[[{"text":"Negotiation","bold":true},{"text":" (exchange something of value, e.g. special pay package)"}],[{"text":"Powerful group"}],[{"text":"Can \"buy\" commitment"}],[{"text":"Can be costly; opens the door for others to demand deals"}]],[[{"text":"Manipulation","bold":true},{"text":" (covert influence: twisting facts) and "},{"text":"co-optation","bold":true},{"text":" (manipulation plus participation: \"buying off\" resistance leaders with a key role)"}],[{"text":"Powerful group's support needed"}],[{"text":"Cheap and easy way to gain support"}],[{"text":"Can backfire; change agent may lose credibility"}]],[[{"text":"Coercion","bold":true},{"text":" (direct threats: transfer, loss of promotion, poor reviews)"}],[{"text":"Powerful group's support needed"}],[{"text":"Cheap and easy way to gain support"}],[{"text":"May be illegal; may undermine the change agent's credibility"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Resistance can give stability and lead to useful debate, but it slows adaptation. People with a lot invested in the current system (long-serving staff) resist most."}]},{"text":[{"text":"Change often creates "},{"text":"stress","bold":true},{"text":"."}]}]}]},{"number":"6.4","title":"Employee stress","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stress:","bold":true},{"text":" the adverse reaction people have to excessive pressure placed on them from extraordinary demands, constraints or opportunities."}]},{"text":[{"text":"Constraints:","bold":true},{"text":" barriers that keep us from doing what we desire. "},{"text":"Demands:","bold":true},{"text":" the loss of something desired."}]},{"text":[{"text":"3 groups of symptoms:","bold":true},{"text":" "},{"text":"physical","bold":true},{"text":" (faster heart and breathing rates, higher blood pressure, headaches); "},{"text":"psychological","bold":true},{"text":" (job dissatisfaction, tension, irritability, boredom, procrastination); "},{"text":"behavioural","bold":true},{"text":" (absenteeism, turnover, more smoking or drinking, rapid speech, fidgeting, sleep problems)."}]},{"text":[{"text":"2 groups of causes:","bold":true},{"text":" 1. "},{"text":"organizational (job-related):","bold":true},{"text":" task demands, role demands, interpersonal demands, organization structure, organizational leadership; 2. "},{"text":"personal:","bold":true},{"text":" family issues, personal economic problems, personality type."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Task demands:","bold":true},{"text":" the job itself (design, conditions, layout). "},{"text":"Interpersonal demands:","bold":true},{"text":" co-workers (poor support). "},{"text":"Organization structure:","bold":true},{"text":" too many rules, little say in decisions. "},{"text":"Organizational leadership:","bold":true},{"text":" a style creating tension, fear and anxiety, with unrealistic pressure to perform."}]},{"text":[{"text":"Stress is not always bad (it can bring opportunity); excess is the problem. "},{"text":"Role conflict","bold":true},{"text":" = expectations hard to meet at once; "},{"text":"role overload","bold":true},{"text":" = more expected than time allows; "},{"text":"role ambiguity","bold":true},{"text":" = expectations unclear."}]},{"text":[{"text":"Type A:","bold":true},{"text":" chronic time urgency, excessive competitive drive, difficulty enjoying leisure. "},{"text":"Type B:","bold":true},{"text":" relaxed, no time urgency or impatience. The harmful part of Type A is "},{"text":"hostility and anger","bold":true},{"text":"."}]},{"text":[{"text":"Reducing stress:","bold":true},{"text":" employee selection (match people to jobs); realistic job preview during selection; clear goals with feedback (MBO) to cut role ambiguity; job redesign; communication during change; employee assistance programmes (EAPs: counselling for personal problems); wellness programmes (fitness, healthy eating, stopping smoking)."}]}]}]},{"number":"6.5","title":"Creativity and innovation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Creativity:","bold":true},{"text":" the ability to combine ideas in a unique way or to make unusual associations between ideas. It produces the idea."}]},{"text":[{"text":"Innovation:","bold":true},{"text":" taking a creative idea and turning it into a useful product, ser$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 21, $study_guide$vice or method of operation. It improves productivity and competitiveness."}]},{"text":[{"text":"Systems view of innovation:","bold":true},{"text":" 1. "},{"text":"inputs:","bold":true},{"text":" creative people and groups; 2. "},{"text":"transformation:","bold":true},{"text":" a creative environment, process and situation; 3. "},{"text":"outputs:","bold":true},{"text":" innovative products and work methods."}]},{"text":[{"text":"Idea champions:","bold":true},{"text":" individuals who actively and enthusiastically support new ideas, build support, overcome resistance and make sure innovations are implemented. Traits: very high self-confidence, persistence, energy, risk-taking."}]},{"text":[{"text":"3 sets of variables that foster innovation:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Structural:","bold":true},{"text":" organic structure (flexible: low formalization, centralization, specialization); abundant resources; frequent communication between units; minimal time pressure; work and nonwork support."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" accept ambiguity; tolerate the impractical; keep external controls low; tolerate risk; tolerate conflict; focus on ends rather than means; open-system focus; give positive feedback."}]},{"text":[{"text":"Human resource:","bold":true},{"text":" actively promote training and development; offer high job security; encourage people to become idea champions."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Abundant resources:","bold":true},{"text":" buy innovations, afford failures, try many ideas. "},{"text":"Minimal time pressure:","bold":true},{"text":" extreme pressure lowers creativity."}]},{"text":[{"text":"Tolerate risk:","bold":true},{"text":" failures not punished. "},{"text":"Open-system focus:","bold":true},{"text":" watching the environment. "},{"text":"High job security:","bold":true},{"text":" less fear of being fired for mistakes."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Change = people, structure or technology; 5 external, 4 internal forces."}]},{"text":[{"text":"Calm waters = Lewin's 3 steps; white-water = constant change; OD changes people (insiders cautious, outsiders may be drastic)."}]},{"text":[{"text":"Stress: 3 symptom groups, 2 cause groups. Resistance: 4 reasons, 6 remedies. Creativity = the idea; innovation = the idea made useful."}]}]}],"theory":{"itemId":"9c690f6d-55fa-51be-9dca-8e0f4183c11f","question":[{"type":"paragraph","text":[{"text":"Explain why employees resist organizational change and discuss the techniques managers can use to reduce resistance."}]}]},"practice":[{"topic":"Managing Change and Innovation","named":false}]}},{"kind":"note","itemId":"006b8fa8-d019-5c9e-ac09-7e00435a3088","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Individual Behaviour, Groups and Work Teams","body":"What OB studies, what shapes individual behaviour, and how groups and teams form, clash and perform.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What OB studies, what shapes individual behaviour, and how groups and teams form, clash and perform."}],"lessons":[{"number":"7.1","title":"Organizational behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Behaviour:","bold":true},{"text":" actions of people. "},{"text":"Organizational behaviour (OB):","bold":true},{"text":" study of the actions of people at work. "},{"text":"2 areas:","bold":true},{"text":" individual and group behaviour. "},{"text":"3 goals:","bold":true},{"text":" explain, predict, influence (not \"eliminate\")."}]},{"text":[{"text":"6 employee behaviours:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Productivity:","bold":true},{"text":" performance measure of efficiency and effectiveness."}]},{"text":[{"text":"Absenteeism:","bold":true},{"text":" failure to show up for work."}]},{"text":[{"text":"Turnover:","bold":true},{"text":" voluntary and involuntary permanent withdrawal from the organization."}]},{"text":[{"text":"OCB (organizational citizenship behaviour):","bold":true},{"text":" discretionary behaviour, not in the formal job, that helps the organization work well."}]},{"text":[{"text":"Job satisfaction:","bold":true},{"text":" general attitude to the job."}]},{"text":[{"text":"Workplace misbehaviour:","bold":true},{"text":" intentional behaviour that could harm the organization or people in it; 4 forms: deviance, aggression, antisocial behaviour, violence."}]}]}]},{"text":[{"text":"Iceberg:","bold":true},{"text":" visible = strategies, objectives, policies, structure, technology, formal authority, chain of command. Hidden = attitudes, perceptions, group norms, informal interactions, interpersonal and intergroup conflicts. Most of what drives behaviour is below the surface."}]},{"text":[{"text":"7 factors influencing individual behaviour:","bold":true},{"text":" biography/demography, age, gender, societal responsibilities, marital status, personality, values and attitudes. "},{"text":"5 factors that change behaviour:","bold":true},{"text":" demographic/biological factors, personality, values and attitudes, motivation, learning."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Owen:","bold":true},{"text":" concerned about terrible working conditions. "},{"text":"Munsterberg:","bold":true},{"text":" founded industrial psychology, the scientific study of people at work. "},{"text":"Follett:","bold":true},{"text":" studied organizations through individual and group behaviour; modern work groups trace to her. "},{"text":"Barnard:","bold":true},{"text":" organizations are social systems needing cooperation; first to call them open systems."}]},{"text":[{"text":"Hawthorne Studies (Elton Mayo):","bold":true},{"text":" began as lighting tests; biggest contribution to OB; found social norms or group standards drive individ$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 22, $study_guide$ual work behaviour."}]},{"text":[{"text":"OB is most tied to employee motivation. Current issues: generational differences, negative behaviour."}]}]}]},{"number":"7.2","title":"Attitudes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Attitudes:","bold":true},{"text":" evaluative statements, favourable or unfavourable, about objects, people or events; show how a person feels."}]},{"text":[{"text":"3 components:","bold":true},{"text":" "},{"text":"cognitive","bold":true},{"text":" (beliefs, opinions, knowledge); "},{"text":"affective","bold":true},{"text":" (emotions, feelings); "},{"text":"behavioural","bold":true},{"text":" (intention to behave a certain way)."}]},{"text":[{"text":"4 job-related attitudes:","bold":true},{"text":" "},{"text":"job satisfaction","bold":true},{"text":" (general attitude to the job); "},{"text":"job involvement","bold":true},{"text":" (identifying with the "},{"text":"job","bold":true},{"text":", active part in it, performance seen as important to self-worth); "},{"text":"organizational commitment","bold":true},{"text":" (identifying with the "},{"text":"organization","bold":true},{"text":" and its goals, wanting to stay); "},{"text":"employee engagement","bold":true},{"text":" (connected to, satisfied with, enthusiastic about the job)."}]},{"text":[{"text":"Cognitive dissonance (Leon Festinger):","bold":true},{"text":" any incompatibility or inconsistency between attitudes, or between behaviour and attitudes."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"People change the attitude or behaviour, or find a reason for the gap. Effort depends on "},{"text":"importance","bold":true},{"text":" of the elements, "},{"text":"influence","bold":true},{"text":" the person feels he has, "},{"text":"rewards","bold":true},{"text":" (high pay eases it)."}]},{"text":[{"text":"Managers measure attitudes with attitude surveys."}]},{"text":[{"text":"Satisfied employees: lower absenteeism and turnover; satisfied, engaged ones: better customer service."}]}]}]},{"number":"7.3","title":"Personality and emotional intelligence","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personality:","bold":true},{"text":" unique combination of emotional, thought and behavioural patterns affecting how a person reacts and interacts with others. From "},{"text":"heredity and environment","bold":true},{"text":". 3 influences: perception, emotions, religion."}]},{"text":[{"text":"Big Five (OCEAN):","bold":true},{"text":" "},{"text":"Openness","bold":true},{"text":" (imaginative, curious, artistically sensitive); "},{"text":"Conscientiousness","bold":true},{"text":" (responsible, dependable, persistent, achievement-oriented; best linked to job performance); "},{"text":"Extraversion","bold":true},{"text":" (sociable, talkative, assertive); "},{"text":"Agreeableness","bold":true},{"text":" (good-natured, cooperative, trusting); "},{"text":"Neuroticism","bold":true},{"text":" (tense, anxious, insecure; opposite = "},{"text":"emotional stability","bold":true},{"text":")."}]},{"text":[{"text":"MBTI:","bold":true},{"text":" 4 dimensions, "},{"text":"16","bold":true},{"text":" types: Extravert/Introvert (social interaction); Sensing/Intuitive (gathering data); Feeling/Thinking (decision making); Perceptive/Judgemental (style of making decisions)."}]},{"text":[{"text":"Other traits:","bold":true},{"text":" "},{"text":"locus of control","bold":true},{"text":" (internal: \"I control my fate\"; external: luck or others; internals more satisfied and involved); "},{"text":"Machiavellianism","bold":true},{"text":" (pragmatic, emotionally distant, ends justify means; suits bargaining jobs such as sales, negotiating); "},{"text":"self-esteem","bold":true},{"text":" (liking or disliking oneself; low = more open to outside influence); "},{"text":"self-monitoring","bold":true},{"text":" (adjusting behaviour to the situation); "},{"text":"risk-taking","bold":true},{"text":" (willingness to take chances; high risk-takers make quick decisions on little information, low risk-takers decide slowly and want more information); "},{"text":"proactive personality","bold":true},{"text":" (spots opportunities, shows initiative, persists until change happens)."}]},{"text":[{"text":"Emotional intelligence (EI):","bold":true},{"text":" ability to notice and manage emotional cues and information. "},{"text":"5 dimensions:","bold":true},{"text":" self-awareness, self-management, self-motivation, empathy, social skills. Matters most in jobs needing much social interaction."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Holland's personality-job fit:","bold":true},{"text":" satisfaction highest, turnover lowest when personality matches job. 6 types: realistic, investigative, social, conventional, enterprising, artistic."}]},{"text":[{"text":"Big Five appear across many cultures; locus of control differs between cultures."}]}]}]},{"number":"7.4","title":"Perception and learning","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Perception:","bold":true},{"text":" giving meaning to our environment by organizing and interpreting sensory impressions. Influenced by the "},{"text":"perceiver","bold":true},{"text":" (attitudes, interests, experience, expectations), the "},{"text":"target","bold":true},{"text":", the "},{"text":"situation","bold":true},{"text":"."}]},{"text":[{"text":"Attribution theory:","bold":true},{"text":" we judge people differently depending on whether we see the cause as internal or external. 3 factors: "},{"text":"distinctiveness","bold":true},{"text":" (acts differently elsewhere? high = external); "},{"text":"consensus","bold":true},{"text":" (others in the same situation act the same? high = external); "},{"text":"consistency","bold":true},{"text":" (acts this way over time? high = internal)."}]},{"text":[{"text":"Fundamental attribution error:","bold":true},{"text":" judging "},{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 23, $study_guide$"others","bold":true},{"text":", we underestimate external and overestimate internal factors. "},{"text":"Self-serving bias:","bold":true},{"text":" we credit "},{"text":"our own","bold":true},{"text":" success to internal factors, failure to external ones (luck)."}]},{"text":[{"text":"4 judging shortcuts:","bold":true},{"text":" "},{"text":"selectivity","bold":true},{"text":" (taking in only bits of what we see, by interests, background, attitudes); "},{"text":"assumed similarity","bold":true},{"text":" (\"like me\" effect); "},{"text":"stereotyping","bold":true},{"text":" (judging by the group someone belongs to); "},{"text":"halo effect","bold":true},{"text":" (one characteristic, such as looks, shapes the whole impression)."}]},{"text":[{"text":"Learning:","bold":true},{"text":" relatively permanent change in behaviour from experience. "},{"text":"Operant conditioning (B. F. Skinner):","bold":true},{"text":" behaviour is a function of its consequences. "},{"text":"Social learning theory:","bold":true},{"text":" learning by observing others and direct experience; 4 processes: attentional, retention, motor reproduction, reinforcement."}]},{"text":[{"text":"4 ways to shape behaviour:","bold":true},{"text":" "},{"text":"positive reinforcement","bold":true},{"text":" (something pleasant follows; strengthens); "},{"text":"negative reinforcement","bold":true},{"text":" (something unpleasant removed, such as nagging stopping; strengthens); "},{"text":"punishment","bold":true},{"text":" (penalty follows; weakens); "},{"text":"extinction","bold":true},{"text":" (reward sustaining the behaviour removed; weakens). "},{"text":"Shaping behaviour:","bold":true},{"text":" guiding learning in graduated steps, reinforcing each step towards the desired behaviour."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Negative reinforcement is not punishment."}]},{"text":[{"text":"Managers should reward wanted behaviour and model it; staff learn from what managers do."}]}]}]},{"number":"7.5","title":"Groups and group behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Group:","bold":true},{"text":" two or more interacting and interdependent individuals who come together to achieve specific goals."}]},{"text":[{"text":"Formal:","bold":true},{"text":" purposeful, structured (hierarchy, rules), assigned roles, officially recognised (e.g. a bank's finance department). "},{"text":"Informal:","bold":true},{"text":" spontaneous, unstructured, based on personal connections and social needs (friendship groups, lunch or football groups, social clubs)."}]},{"text":[{"text":"2 formal types:","bold":true},{"text":" "},{"text":"command group","bold":true},{"text":" (set by the organization chart: supervisor and direct subordinates); "},{"text":"task group","bold":true},{"text":" (specific task, set time; disbands after)."}]},{"text":[{"text":"5 stages in order:","bold":true},{"text":" 1. "},{"text":"Forming:","bold":true},{"text":" people join; purpose, structure, leadership defined; uncertainty. 2. "},{"text":"Storming:","bold":true},{"text":" conflict over control and direction; ends when a clear leadership hierarchy emerges. 3. "},{"text":"Norming:","bold":true},{"text":" close relationships, cohesiveness, shared expectations. 4. "},{"text":"Performing:","bold":true},{"text":" structure accepted; energy on the task; last stage for permanent groups. 5. "},{"text":"Adjourning:","bold":true},{"text":" temporary groups wrap up and break up."}]},{"text":[{"text":"Role:","bold":true},{"text":" behaviour patterns expected of someone in a given position. "},{"text":"Role conflict:","bold":true},{"text":" facing different role expectations at once."}]},{"text":[{"text":"Norms:","bold":true},{"text":" standards accepted and shared by members; commonly cover work effort and performance. "},{"text":"Asch study:","bold":true},{"text":" many went along with a deliberately wrong group answer on line lengths: pressure to conform."}]},{"text":[{"text":"Status:","bold":true},{"text":" prestige grading, position or rank in a group; formal (title, office) or informal (education, age, skill). Members must see it as fair."}]},{"text":[{"text":"Size:","bold":true},{"text":" small groups finish tasks faster; large groups suit problem solving and diverse input."}]},{"text":[{"text":"Social loafing:","bold":true},{"text":" less effort when working collectively than alone. Reduce it by making each contribution identifiable and measurable."}]},{"text":[{"text":"Cohesiveness:","bold":true},{"text":" how far members are attracted to the group and share its goals. Productivity: high and aligned with organization goals = strong increase; high, not aligned = decrease; low, aligned = moderate increase; low, not aligned = no significant effect."}]},{"text":[{"text":"Groupthink:","bold":true},{"text":" heavy group pressure on an individual to align his opinion with the others."}]},{"text":[{"text":"Group decisions:","bold":true},{"text":" advantages: more complete information, more diverse alternatives, greater acceptance, greater legitimacy. Disadvantages: time-consuming, minority domination, pressure to conform, ambiguous responsibility (unclear who is accountable)."}]}]}]},{"number":"7.6","title":"Teams and conflict","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Work team:","bold":true},{"text":" members work intensely on a specific, common goal using positive synergy (whole greater than sum of parts), individual and mutual accountability, complementary skills."}]},{"text":[{"text":"5 differences, groups vs teams:","bold":true},{"text":" accountability (individual / shared); goals (individual / shared); interdependence (limited / high); focus (individual / collective performance); collaboration (less / heavy emphasis). Leadership: one leader in charge in a group; often shared in a team."}]},{"text":[{"text":"4 team types:","bold":true},{"text":" "},{"text":"problem-solv$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 24, $study_guide$ing","bold":true},{"text":" (same department; suggests improvements, usually cannot carry them out); "},{"text":"self-managed","bold":true},{"text":" (no manager; whole work process; plans, schedules, assigns work, decides); "},{"text":"cross-functional","bold":true},{"text":" (different departments or specialities); "},{"text":"virtual","bold":true},{"text":" (linked by technology while apart)."}]},{"text":[{"text":"8 characteristics of effective teams:","bold":true},{"text":" clear goals, relevant skills, mutual trust, unified commitment, good communication, negotiating skills, appropriate leadership, internal and external support."}]},{"text":[{"text":"Conflict:","bold":true},{"text":" perceived incompatible differences resulting in interference or opposition. "},{"text":"3 views:","bold":true},{"text":" "},{"text":"traditional","bold":true},{"text":" (bad, avoid it); "},{"text":"human relations","bold":true},{"text":" (natural, inevitable, need not be negative); "},{"text":"interactionist","bold":true},{"text":" (some conflict is necessary for good performance)."}]},{"text":[{"text":"Functional","bold":true},{"text":" conflict supports group goals and improves performance; "},{"text":"dysfunctional","bold":true},{"text":" prevents reaching them."}]},{"text":[{"text":"3 types:","bold":true},{"text":" "},{"text":"task","bold":true},{"text":" (content and goals of work); "},{"text":"relationship","bold":true},{"text":" (interpersonal; almost always dysfunctional); "},{"text":"process","bold":true},{"text":" (how work gets done)."}]},{"text":[{"text":"5 handling styles:","bold":true},{"text":" "},{"text":"avoiding","bold":true},{"text":" (withdraw or suppress); "},{"text":"accommodating","bold":true},{"text":" (other's needs above yours); "},{"text":"forcing","bold":true},{"text":" (yours at the other's expense); "},{"text":"compromising","bold":true},{"text":" (each gives up something); "},{"text":"collaborating","bold":true},{"text":" (win-win for all)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Too little conflict: dull, slow to change. Too much: chaos."}]},{"text":[{"text":"Managers shape team behaviour by "},{"text":"selection, training, rewards","bold":true},{"text":" (reward cooperation and team results, not only individual effort)."}]},{"text":[{"text":"Global teams bring more ideas but face language, culture and trust problems."}]},{"text":[{"text":"Teams cost more time and resources; use when work is complex, needs different perspectives and members depend on one another."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"OB: actions of people at work; explain, predict, influence."}]},{"text":[{"text":"Big Five OCEAN; MBTI 16 types; EI 5 dimensions."}]},{"text":[{"text":"Attribution: distinctiveness, consensus, consistency."}]},{"text":[{"text":"Reinforcement strengthens; punishment and extinction weaken."}]},{"text":[{"text":"Stages: forming, storming, norming, performing, adjourning."}]},{"text":[{"text":"Conflict: 3 views, 3 types, 5 styles."}]}]}],"theory":{"itemId":"42bbfaf2-990f-56e5-b3bd-ae66a546c271","question":[{"type":"paragraph","text":[{"text":"Distinguish between a group and a team, and explain the five stages of group development."}]}]},"practice":[{"topic":"Individual Behaviour, Groups and Work Teams","named":false}]}},{"kind":"note","itemId":"afc18495-3b1b-51ab-8888-85221395539d","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Motivating and Rewarding Employees","body":"The theories of motivation, how they fit together, and how to design rewards.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The theories of motivation, how they fit together, and how to design rewards."}],"lessons":[{"number":"8.1","title":"What motivation is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation:","bold":true},{"text":" the process by which a person's efforts are energized, directed and sustained toward attaining a goal; put simply, "},{"text":"encouraging employees to work effectively","bold":true},{"text":". It belongs to "},{"text":"leading","bold":true},{"text":"."}]},{"text":[{"text":"3 elements:","bold":true},{"text":" 1. "},{"text":"Energy","bold":true},{"text":" (intensity or drive); 2. "},{"text":"Direction","bold":true},{"text":" (effort channelled toward organizational goals); 3. "},{"text":"Persistence","bold":true},{"text":" (effort continues until the goal is achieved)."}]},{"text":[{"text":"Process, 6 steps:","bold":true},{"text":" unsatisfied need → tension → drives → search behaviour → satisfied need (also worded \"satisfying behaviour\" or \"satisfied behaviour\") → reduction of tension."}]},{"text":[{"text":"Motivating employees effectively requires "},{"text":"understanding their individual needs and goals","bold":true},{"text":"; one size does not fit all."}]},{"text":[{"text":"Intrinsic:","bold":true},{"text":" from inside (achievement, enjoying the work). "},{"text":"Extrinsic:","bold":true},{"text":" external rewards (pay, bonuses, promotion, recognition)."}]},{"text":[{"text":"Content theories (what motivates):","bold":true},{"text":" Maslow, Herzberg, McClelland. "},{"text":"Process theories (how motivation works):","bold":true},{"text":" Vroom, Adams, Locke and Latham."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Satisfaction is not an element. Vroom is process, not content."}]}]}]},{"number":"8.2","title":"Early theories of motivation","mustKnow":[{"type":"paragraph","text":[{"text":"1. Maslow's hierarchy of needs (Abraham Maslow),","bold":true},{"text":" lowest to highest:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physiological:","bold":true},{"text":" food, water, shelter (\"primary needs\")."}]},{"text":[{"text":"Safety:","bold":true},{"text":" protection from harm, job security, health insurance, pension."}]},{"text":[{"text":"Social:","bold":true},{"text":" affection, bel$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 25, $study_guide$onging, acceptance, friendship."}]},{"text":[{"text":"Esteem:","bold":true},{"text":" internal (self-respect, autonomy, achievement); external (status, recognition, attention)."}]},{"text":[{"text":"Self-actualization:","bold":true},{"text":" growth, achieving one's potential."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lower-order:","bold":true},{"text":" physiological, safety; satisfied "},{"text":"externally","bold":true},{"text":" (pay, contracts, tenure). "},{"text":"Higher-order:","bold":true},{"text":" the other three; satisfied "},{"text":"internally","bold":true},{"text":"."}]},{"text":[{"text":"Assumptions:","bold":true},{"text":" behaviour is based on needs; needs come in a fixed order; a satisfied need no longer motivates, so the person moves up."}]}]},{"type":"paragraph","text":[{"text":"2. McGregor (Douglas McGregor).","bold":true},{"text":" "},{"text":"Theory X","bold":true},{"text":" (negative): little ambition, dislike work, avoid responsibility, need close control. "},{"text":"Theory Y","bold":true},{"text":" (positive): self-direction, accept and seek responsibility, see work as natural."}]},{"type":"paragraph","text":[{"text":"3. Herzberg's two-factor (motivation-hygiene) theory (Frederick Herzberg).","bold":true}]},{"type":"table","header":[[{"text":"Hygiene factors ("},{"text":"extrinsic","bold":true},{"text":")"}],[{"text":"Motivators ("},{"text":"intrinsic","bold":true},{"text":")"}]],"rows":[[[{"text":"Remove dissatisfaction; do not motivate"}],[{"text":"Create satisfaction; motivate; concern the job itself"}]],[[{"text":"Salary, company policy, supervision, working conditions, relations with others, job security"}],[{"text":"Achievement, recognition, the work itself, responsibility, advancement, growth"}]]]},{"type":"paragraph","text":[{"text":"4. McClelland's three needs (David McClelland):","bold":true},{"text":" "},{"text":"Achievement","bold":true},{"text":" (drive to succeed and excel in relation to a set of standards); "},{"text":"Power","bold":true},{"text":" (need to make others behave in a way they would not have behaved otherwise); "},{"text":"Affiliation","bold":true},{"text":" (desire for friendly and close interpersonal relationships)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Maslow:","bold":true},{"text":" helps managers understand what motivates each employee. Status and recognition are esteem, not social."}]},{"text":[{"text":"McGregor","bold":true},{"text":" favoured Theory Y: participation in decisions, responsible and challenging jobs, good group relations. No evidence either set is valid or that Theory Y always raises motivation."}]},{"text":[{"text":"Herzberg:","bold":true},{"text":" opposite of satisfaction = "},{"text":"no satisfaction","bold":true},{"text":"; opposite of dissatisfaction = "},{"text":"no dissatisfaction","bold":true},{"text":". Fixing hygiene makes workers calm, not motivated. His work led to "},{"text":"job enrichment","bold":true},{"text":"."}]},{"text":[{"text":"McClelland:","bold":true},{"text":" high achievers want personal responsibility, fast feedback, "},{"text":"moderate","bold":true},{"text":" risk. Best managers tend to be "},{"text":"high in power, low in affiliation","bold":true},{"text":"."}]}]}]},{"number":"8.3","title":"Goal-setting and reinforcement","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Goal-setting theory (Edwin Locke, later with Gary Latham):","bold":true},{"text":" specific and challenging goals motivate. "},{"text":"Clear","bold":true},{"text":", "},{"text":"difficult but attainable","bold":true},{"text":" goals "},{"text":"with feedback","bold":true},{"text":" raise performance. Specific beats \"do your best\"; accepted difficult goals beat easy ones."}]},{"text":[{"text":"SMART:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"pecific (clear, well defined); "},{"text":"M","bold":true},{"text":"easurable (progress tracked with numbers); "},{"text":"A","bold":true},{"text":"chievable/attainable (realistic, within reach; goals that are too difficult cause "},{"text":"discouragement","bold":true},{"text":"); "},{"text":"R","bold":true},{"text":"elevant (fits objectives and values); "},{"text":"T","bold":true},{"text":"ime-bound (deadline)."}]},{"text":[{"text":"Reinforcement theory (B. F. Skinner):","bold":true},{"text":" behaviour is a function of its consequences. "},{"text":"Reinforcers:","bold":true},{"text":" consequences that, coming immediately after a behaviour, increase the chance it will be repeated."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Self-generated feedback","bold":true},{"text":" (tracking own progress) beats feedback from others."}]},{"text":[{"text":"Participation does not always beat assigned goals, but makes people "},{"text":"accept","bold":true},{"text":" a hard goal."}]},{"text":[{"text":"Other conditions: "},{"text":"goal commitment","bold":true},{"text":", "},{"text":"self-efficacy","bold":true},{"text":" (belief one can do the task), task type, national culture. "},{"text":"MBO","bold":true},{"text":" applies goal-setting."}]},{"text":[{"text":"Reinforcement ignores inner needs, goals and expectations. "},{"text":"Ignore","bold":true},{"text":" rather than punish unwanted behaviour: punishment works faster but is often temporary, with unpleasant side effects."}]},{"text":[{"text":"Trap:","bold":true},{"text":" goal-setting = goal "},{"text":"before","bold":true},{"text":" the action; reinforcement = consequence "},{"text":"after","bold":true},{"text":" it."}]}]}]},{"number":"8.4","title":"Job design and the job characteristics model","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job design:","bold":true},{"text":" the way tasks are combined to form complete jobs. "},{"text":"Job scope:","bold":true},{"text":" number of different tasks and how often repeated. "},{"text":"Job depth:","bold":true},{"text":" degree of $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 26, $study_guide$control over the work."}]},{"text":[{"text":"Job enlargement:","bold":true},{"text":" "},{"text":"horizontal","bold":true},{"text":" expansion, increasing scope (more tasks of the same kind). "},{"text":"Job enrichment:","bold":true},{"text":" "},{"text":"vertical","bold":true},{"text":" expansion, adding planning and evaluating responsibilities (increases depth)."}]},{"text":[{"text":"Job characteristics model (Hackman and Oldham): 5 core dimensions:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Skill variety:","bold":true},{"text":" range of activities, skills, talents."}]},{"text":[{"text":"Task identity:","bold":true},{"text":" completing a whole, identifiable piece of work."}]},{"text":[{"text":"Task significance:","bold":true},{"text":" effect on the lives or work of others."}]},{"text":[{"text":"Autonomy:","bold":true},{"text":" freedom and discretion in scheduling and choosing methods."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" direct, clear information on performance."}]}]}]},{"text":[{"text":"3 critical psychological states:","bold":true},{"text":" skill variety + task identity + task significance → "},{"text":"experienced meaningfulness","bold":true},{"text":"; autonomy → "},{"text":"experienced responsibility","bold":true},{"text":"; feedback → "},{"text":"knowledge of actual results","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Outcomes: high internal motivation, performance quality, satisfaction, "},{"text":"low","bold":true},{"text":" absenteeism and turnover. Works best for high "},{"text":"growth-need strength","bold":true},{"text":" (a trait, not a dimension). Job enrichment is a "},{"text":"non-financial","bold":true},{"text":" incentive."}]}]}]},{"number":"8.5","title":"Equity, expectancy and integration","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equity theory (J. Stacy Adams):","bold":true},{"text":" an employee compares their "},{"text":"input-outcome ratio","bold":true},{"text":" with that of relevant others and acts to correct inequity. "},{"text":"Inputs:","bold":true},{"text":" effort, experience, education, skill. "},{"text":"Outcomes:","bold":true},{"text":" pay, recognition, promotion."}]},{"text":[{"text":"3 referents:","bold":true},{"text":" 1. "},{"text":"Other","bold":true},{"text":" (similar jobs in the organization, friends, neighbours, professional associates); 2. "},{"text":"System","bold":true},{"text":" (pay policies and procedures); 3. "},{"text":"Self","bold":true},{"text":" (own past experience)."}]},{"text":[{"text":"Expectancy theory (Victor Vroom):","bold":true},{"text":" a person acts based on the expectation that the act will bring a given outcome and on how attractive that outcome is. "},{"text":"3 linkages:","bold":true},{"text":" 1. "},{"text":"Expectancy","bold":true},{"text":" (effort-performance); 2. "},{"text":"Instrumentality","bold":true},{"text":" (performance-reward); 3. "},{"text":"Valence","bold":true},{"text":" (attractiveness of reward)."}]},{"text":[{"text":"Integrated model:","bold":true},{"text":" expectancy theory is the base. Chain: individual effort → individual performance → organizational rewards → individual goals. "},{"text":"Opportunity","bold":true},{"text":" to perform also affects performance. Goal-setting: goals direct effort. Reinforcement: rewards reinforce behaviour. Equity: rewards must feel fair. Needs theories: rewards meet needs. JCM: a well-designed job raises motivation directly."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ratio lower than referent's = "},{"text":"under-rewarded","bold":true},{"text":"; higher = "},{"text":"over-rewarded","bold":true},{"text":"."}]},{"text":[{"text":"Responses to inequity:","bold":true},{"text":" distort own or others' inputs or outcomes; make others change theirs; change own inputs or outcomes (work less); choose a different referent; quit."}]},{"text":[{"text":"Distributive justice:","bold":true},{"text":" fairness of the "},{"text":"amount","bold":true},{"text":" and allocation of rewards; affects "},{"text":"satisfaction","bold":true},{"text":" more. "},{"text":"Procedural justice:","bold":true},{"text":" fairness of the "},{"text":"process","bold":true},{"text":"; affects commitment, trust in the boss, intention to quit."}]},{"text":[{"text":"Motivation is low if "},{"text":"any one","bold":true},{"text":" linkage is weak. What counts is "},{"text":"perception","bold":true},{"text":". A reward staff do not want = low valence; doubting a promised bonus will be paid = weak instrumentality."}]}]}]},{"number":"8.6","title":"Current motivation issues and designing rewards","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tough economic times:","bold":true},{"text":" find creative ways to keep efforts energized, directed and sustained. "},{"text":"Cross-cultural challenge:","bold":true},{"text":" most theories were developed in the United States, so do not fit every culture."}]},{"text":[{"text":"Flexible work arrangements:","bold":true},{"text":" "},{"text":"compressed workweek","bold":true},{"text":" (longer days, fewer days); "},{"text":"flextime","bold":true},{"text":" (set weekly hours, start and end times vary within limits around common core hours); "},{"text":"job sharing","bold":true},{"text":" (two or more people split one full-time job); "},{"text":"telecommuting","bold":true},{"text":" (working from home, linked by computer)."}]},{"text":[{"text":"Unique groups:","bold":true},{"text":" "},{"text":"professionals","bold":true},{"text":" want job challenge, keeping up with their field, support and recognition; "},{"text":"contingent workers","bold":true},{"text":" want a chance to become permanent and training; "},{"text":"low-skilled, minimum-wage workers","bold":true},{"text":" respond to recognition programmes and sincere praise."}]},{"text":[{"text":"3 ways t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 27, $study_guide$o design rewards:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Open-book management:","bold":true},{"text":" financial statements shared with all employees, who learn to read them and see how their work affects results."}]},{"text":[{"text":"Employee recognition programmes:","bold":true},{"text":" personal attention; interest, approval, appreciation for a job well done."}]},{"text":[{"text":"Pay-for-performance programmes:","bold":true},{"text":" variable pay based on a performance measure: piece-rate pay, wage incentive plans, profit-sharing, lump-sum bonuses."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Culture:","bold":true},{"text":" Maslow's order fits American culture; where people strongly avoid uncertainty "},{"text":"safety","bold":true},{"text":" can top it, where caring and relationships matter most "},{"text":"social","bold":true},{"text":" can. McClelland's high achiever fits cultures like the United States. Interesting work, growth and achievement appear across cultures."}]},{"text":[{"text":"Professionals' loyalty is often to their "},{"text":"profession","bold":true},{"text":" more than their employer. Watch "},{"text":"equity","bold":true},{"text":" problems when contingent workers sit beside better-paid permanent staff. Pay-for-performance fits "},{"text":"expectancy theory","bold":true},{"text":"."}]},{"text":[{"text":"Financial incentives:","bold":true},{"text":" pay rises, bonuses, profit-sharing, piece-rate pay, perquisites, co-partnership. "},{"text":"Non-financial:","bold":true},{"text":" praise, recognition, job enrichment, flexible hours."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation = efforts energized, directed, sustained toward a goal. Content: Maslow, Herzberg, McClelland. Process: Vroom, Adams, Locke and Latham."}]},{"text":[{"text":"Maslow has 5 needs; McClelland 3. Herzberg: hygiene (incl. salary) vs motivators."}]},{"text":[{"text":"SMART: specific, measurable, achievable, relevant, time-bound. Reinforcement (Skinner): consequences shape behaviour."}]},{"text":[{"text":"Enlargement = horizontal, scope; enrichment = vertical, depth. JCM: 5 dimensions, 3 states."}]},{"text":[{"text":"Equity: other, system, self. Expectancy: expectancy, instrumentality, valence."}]},{"text":[{"text":"3 reward designs: open-book management, recognition programmes, pay-for-performance."}]}]}],"theory":{"itemId":"a46fb73b-a0ea-527f-8974-fb4bb16711f4","question":[{"type":"paragraph","text":[{"text":"Explain Herzberg's two-factor theory and state its implications for managers."}]}]},"practice":[{"topic":"Motivating and Rewarding Employees","named":false}]}},{"kind":"note","itemId":"18df4c53-1fb8-5ed5-9e1b-744f42576d18","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Leadership and Trust, and Managing Communication and Information","body":"Leadership theories, power, trust, empowerment; the communication process, types, barriers, networks; information technology.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"Leadership theories, power, trust, empowerment; the communication process, types, barriers, networks; information technology."}],"lessons":[{"number":"9.1","title":"Leadership, leaders and traits","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership:","bold":true},{"text":" an influence process that involves motivating and inspiring people to work together to achieve a common goal."}]},{"text":[{"text":"Leader:","bold":true},{"text":" someone who can influence others and who has managerial authority."}]},{"text":[{"text":"9 obligations:","bold":true},{"text":" developing and communicating a clear vision; motivating and inspiring; setting clear expectations; making informed decisions; fostering commitment and accountability; fostering a positive work environment; delegating tasks; coaching team members; conflict resolution."}]},{"text":[{"text":"Manager:","bold":true},{"text":" appointed; influence from formal authority; focus on planning, organizing, controlling. "},{"text":"Leader:","bold":true},{"text":" appointed or emerges from a group; influence can go beyond formal authority; focus on influencing and inspiring."}]},{"text":[{"text":"Trait theories:","bold":true},{"text":" research that tried to isolate the characteristics that set leaders apart from non-leaders."}]},{"text":[{"text":"7 traits:","bold":true},{"text":" drive, desire to lead, honesty and integrity, self-confidence, intelligence, job-relevant knowledge, extraversion."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ideally all managers should be leaders; not all leaders have a manager's abilities."}]},{"text":[{"text":"Supervision:","bold":true},{"text":" overseeing subordinates' work and giving instructions to ensure optimum use of resources and achievement of work targets."}]},{"text":[{"text":"Delegation:","bold":true},{"text":" match tasks to employees' skills and abilities; improves motivation and performance. The manager stays accountable."}]},{"text":[{"text":"8th trait in later lists: "},{"text":"proneness to guilt","bold":true},{"text":" (strong sense of responsibility to others). Flexibility and communication skills also mark effective leaders."}]},{"text":[{"text":"Weakness of trait theories:","bold":true},{"text":" ignored the situation and leader–group interaction. Traits only make a person more likely to be effective. Researchers then studied what leaders "},{"text":"do","bold":true},{"text":"."}]}]}]},{"number":"9.2","title":"Behavioural theories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Behavioural theories:","bold":true},{"text":" identify behaviours that separate effective from ineffective leaders."}]},{"text":[{"text":"Iowa (Kurt Lewin):","bold":true},{"text":" autocratic, democratic, laissez-faire; members more satisfied under democratic leaders. Lewin$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 28, $study_guide$'s early finding: democratic gave good quantity and quality; later studies mixed on performance."}]},{"text":[{"text":"Ohio State:","bold":true},{"text":" initiating structure, consideration; high–high leaders often, not always, got good results."}]},{"text":[{"text":"Michigan:","bold":true},{"text":" employee-oriented, production-oriented; employee-oriented had higher productivity and satisfaction."}]},{"text":[{"text":"Managerial Grid (Blake and Mouton):","bold":true},{"text":" concern for people, concern for production; 9,9 best."}]},{"text":[{"text":"Autocratic:","bold":true},{"text":" centralises authority, dictates work methods, decides alone, limits participation. Best in a "},{"text":"crisis","bold":true},{"text":"."}]},{"text":[{"text":"Democratic:","bold":true},{"text":" involves employees in decisions, delegates authority, uses feedback to coach. Most participatory; suits a team whose ideas improve the decision."}]},{"text":[{"text":"Laissez-faire:","bold":true},{"text":" gives group complete freedom to decide and work. Best with "},{"text":"highly skilled, self-motivated","bold":true},{"text":" employees."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Democratic leader still takes part in the decision; laissez-faire hands it over entirely."}]},{"text":[{"text":"Initiating structure:","bold":true},{"text":" how far a leader defines his role and members' roles to reach goals. "},{"text":"Consideration:","bold":true},{"text":" mutual trust and respect for members' ideas and feelings."}]},{"text":[{"text":"Employee-oriented:","bold":true},{"text":" relationships, employees' needs. "},{"text":"Production-oriented:","bold":true},{"text":" technical or task side. People side: consideration, employee-oriented."}]},{"text":[{"text":"Grid:","bold":true},{"text":" 9 × 9 = "},{"text":"81","bold":true},{"text":" positions; first number = "},{"text":"production","bold":true},{"text":", second = "},{"text":"people","bold":true},{"text":". 1,1 impoverished; 9,1 task management; 1,9 country club (high people, low production); 5,5 middle of the road ("},{"text":"medium","bold":true},{"text":" concern for both production and people); 9,9 team management."}]},{"text":[{"text":"Weakness:","bold":true},{"text":" ignored the situation, leading to contingency theories."}]}]}]},{"number":"9.3","title":"Contingency theories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Contingency theory:","bold":true},{"text":" no one best style; leadership effectiveness depends on understanding employee needs and adapting leadership style to the situation, never keeping a single style regardless of context."}]},{"text":[{"text":"Fiedler:","bold":true},{"text":" performance depends on matching leader's style to how much the situation lets him control and influence. Style "},{"text":"fixed","bold":true},{"text":"."}]},{"text":[{"text":"Situational Leadership Theory (Hersey and Blanchard):","bold":true},{"text":" depends on follower "},{"text":"readiness","bold":true},{"text":" (and task demands). Style "},{"text":"can change","bold":true},{"text":"."}]},{"text":[{"text":"Path-goal (Robert House):","bold":true},{"text":" leader helps followers reach their goals with direction and support."}]},{"text":[{"text":"Fiedler's 3 factors:","bold":true},{"text":" "},{"text":"leader–member relations","bold":true},{"text":" (confidence, trust, respect for the leader); "},{"text":"task structure","bold":true},{"text":" (how formal and structured tasks are); "},{"text":"position power","bold":true},{"text":" (over hiring, firing, discipline, promotion, pay)."}]},{"text":[{"text":"Readiness:","bold":true},{"text":" followers' ability "},{"text":"and","bold":true},{"text":" willingness. R1 unable, unwilling: "},{"text":"telling","bold":true},{"text":" (high task, low relationship). R2 unable, willing: "},{"text":"selling","bold":true},{"text":" (high, high). R3 able, unwilling: "},{"text":"participating","bold":true},{"text":" (low task, high relationship). R4 able, willing: "},{"text":"delegating","bold":true},{"text":" (low, low). As readiness rises, leader cuts back both control and relationship behaviour."}]},{"text":[{"text":"4 path-goal behaviours:","bold":true},{"text":" directive, supportive, participative, achievement-oriented."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"LPC","bold":true},{"text":" (least-preferred co-worker): describing him kindly = high LPC = "},{"text":"relationship-oriented","bold":true},{"text":"; low LPC = "},{"text":"task-oriented","bold":true},{"text":"."}]},{"text":[{"text":"3 factors give "},{"text":"8","bold":true},{"text":" situations. Task-oriented do best in very favourable or very unfavourable; relationship-oriented in moderately favourable. Fix mismatch by "},{"text":"changing the leader or the situation","bold":true},{"text":"."}]},{"text":[{"text":"Directive:","bold":true},{"text":" tells what is expected, schedules work. "},{"text":"Supportive:","bold":true},{"text":" friendly, concerned for needs. "},{"text":"Participative:","bold":true},{"text":" consults, uses suggestions. "},{"text":"Achievement-oriented:","bold":true},{"text":" challenging goals, expects top performance."}]},{"text":[{"text":"Path-goal depends on "},{"text":"environment","bold":true},{"text":" (task structure, formal authority, work group) and "},{"text":"follower characteristics","bold":true},{"text":" (locus of control, experience, perceived ability)."}]},{"text":[{"text":"Leader–member exchange (LMX):","bold":true},{"text":" "},{"text":"in-group","bold":true},{"text":" and "},{"text":"out-group","bold":true},{"text":"; in-group gets more trust and attention."}]}]}]},{"number":"9.4","title":"Contemporary leadership, power, trust and empowerment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership styles:","bold":true},{"text":" autocratic, democratic, laissez-faire, transactional, transformation$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 29, $study_guide$al, charismatic, visionary. \"Functional\" is not a leadership style."}]},{"text":[{"text":"Transactional:","bold":true},{"text":" motivates by "},{"text":"exchanging rewards","bold":true},{"text":" for productivity, through clear goals."}]},{"text":[{"text":"Transformational:","bold":true},{"text":" "},{"text":"stimulates and inspires","bold":true},{"text":" followers to extraordinary outcomes; encourages innovation, creativity, personal growth. Built "},{"text":"on top of","bold":true},{"text":" transactional, not its opposite."}]},{"text":[{"text":"Charismatic:","bold":true},{"text":" enthusiastic, self-confident; personality and actions influence people; personal charm and vision."}]},{"text":[{"text":"Visionary leadership:","bold":true},{"text":" creating and expressing a realistic, credible, attractive vision of the future that improves on the present."}]},{"text":[{"text":"5 powers:","bold":true},{"text":" "},{"text":"legitimate","bold":true},{"text":" (from position); "},{"text":"coercive","bold":true},{"text":" (punish or control); "},{"text":"reward","bold":true},{"text":" (give positive rewards); "},{"text":"expert","bold":true},{"text":" (expertise, skills, knowledge); "},{"text":"referent","bold":true},{"text":" (desirable resources or personal traits; people admire him, want to be like him)."}]},{"text":[{"text":"Trust:","bold":true},{"text":" belief in the integrity, character and ability of a leader. Makes people feel secure and confident: better collaboration, engagement, success."}]},{"text":[{"text":"5 Cs (how trust is built):","bold":true},{"text":" competence (skills, expertise), communication (clear), commitment (to organization's goals), caring (about others), character (ethical, honest)."}]},{"text":[{"text":"Empowerment:","bold":true},{"text":" increasing decision-making discretion of workers."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"5 charismatic characteristics:","bold":true},{"text":" have a vision; express it; take risks for it; sensitive to environmental limits and followers' needs; behave out of the ordinary."}]},{"text":[{"text":"Team leadership:","bold":true},{"text":" 2 priorities: managing external boundary, helping team process. "},{"text":"4 roles:","bold":true},{"text":" liaison with outsiders, troubleshooter, conflict manager, coach."}]},{"text":[{"text":"5 dimensions of trust:","bold":true},{"text":" integrity (honesty; "},{"text":"most important","bold":true},{"text":"), competence, consistency (reliability, good judgement), loyalty (willingness to protect a person), openness."}]},{"text":[{"text":"Credibility:","bold":true},{"text":" followers see leader as honest, competent, able to inspire. "},{"text":"Honesty","bold":true},{"text":" most linked."}]},{"text":[{"text":"Empowered workers decide alone: they know the job best and act fast. Do not mix the 5 Cs (how trust is built) with the 5 dimensions (what it is made of)."}]}]}]},{"number":"9.5","title":"Communication, its process and types","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication:","bold":true},{"text":" transfer and understanding of meaning; "},{"text":"two-way","bold":true},{"text":" between sender and receiver. "},{"text":"Lifeblood","bold":true},{"text":" of organizations; enables coordination."}]},{"text":[{"text":"Effective:","bold":true},{"text":" people understand your meaning and reply in terms that move the exchange forward."}]},{"text":[{"text":"3 rules for clarity:","bold":true},{"text":" be clear in your own mind about what you want to communicate; deliver succinctly; ensure it is clearly and correctly understood."}]},{"text":[{"text":"4 functions:","bold":true},{"text":" "},{"text":"control","bold":true},{"text":" (rules, policies, reporting lines direct behaviour); "},{"text":"motivation","bold":true},{"text":" (what to do, how well, how to improve); "},{"text":"emotional expression","bold":true},{"text":" (sharing feelings, frustration, satisfaction); "},{"text":"information","bold":true},{"text":" (data for decisions)."}]},{"text":[{"text":"Process, 7 parts in order:","bold":true},{"text":" sender, encoding, message, channel, decoding, receiver, feedback. "},{"text":"Noise","bold":true},{"text":" (illegible print, phone static, inattention) can hit any stage; not one of the 7."}]},{"text":[{"text":"Encoding:","bold":true},{"text":" sender turns message into symbols. "},{"text":"Decoding:","bold":true},{"text":" receiver translates it. "},{"text":"Channel:","bold":true},{"text":" the medium. "},{"text":"Feedback:","bold":true},{"text":" last; checks understanding."}]},{"text":[{"text":"5 types:","bold":true},{"text":" "},{"text":"written words","bold":true},{"text":" (memos, reports, proposals, contracts); "},{"text":"spoken words","bold":true},{"text":" (interviews, phone calls, debates, announcements; effective only when heard by the right people); "},{"text":"symbolic gestures","bold":true},{"text":" (facial expressions, tone of voice, silence, posture, absence; any behaviour audience can see or hear); "},{"text":"visual images","bold":true},{"text":" (photographs, charts, logos, colour schemes); "},{"text":"multimedia","bold":true},{"text":" (combines visual-image methods: television, radio, newspapers, flyers, posters, internet)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interpersonal:","bold":true},{"text":" between two or more people. "},{"text":"Organizational:","bold":true},{"text":" all patterns, networks, systems within an organization."}]},{"text":[{"text":"Nonverbal:","bold":true},{"text":" sent without words. "},{"text":"Body language:","bold":true},{"text":" gestures, facial expressions, body movements. "},{"text":"Verbal intonation:","bold":true},{"text":" emphasis on words or phrases."}]},{"text":[{"text":"Face-to-face","bold":true},{"text":" gives most immediate feedback. The sender encodes; the receiver decodes."}]}]}]},{"number":"9.6","title"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 30, $study_guide$:"Feedback, barriers, organizational communication and information","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Feedback","bold":true},{"text":" checks you understood the other person's message and lets you react. Negative feedback must be given when it is the only thing to do."}]},{"text":[{"text":"5 rules for negative feedback:","bold":true},{"text":" show understanding of exactly what went wrong, and why; draw out ways to improve; use questions rather than assertions; express negative opinions honestly but positively; be objective, not emotional or personal."}]},{"text":[{"text":"Sandwich approach:","bold":true},{"text":" praise, criticism, praise."}]},{"text":[{"text":"6 barriers:","bold":true},{"text":" "},{"text":"filtering","bold":true},{"text":" (deliberately changing information to look better to receiver); "},{"text":"emotions","bold":true},{"text":" (receiver's feelings change how he reads it); "},{"text":"information overload","bold":true},{"text":" (more than a person can process); "},{"text":"defensiveness","bold":true},{"text":" (feeling threatened, reacting with attack or sarcasm); "},{"text":"language","bold":true},{"text":" (words differ by age, education, jargon); "},{"text":"national culture","bold":true},{"text":" (cultures communicate differently)."}]},{"text":[{"text":"5 remedies:","bold":true},{"text":" use feedback, simplify language, listen actively, constrain emotions, watch nonverbal cues. "},{"text":"Active listening:","bold":true},{"text":" listen for full meaning without judging early: eye contact, questions, paraphrasing, no interrupting."}]},{"text":[{"text":"Formal:","bold":true},{"text":" follows chain of command or needed to do a job. "},{"text":"Informal:","bold":true},{"text":" not defined by the hierarchy. "},{"text":"Grapevine:","bold":true},{"text":" the informal network."}]},{"text":[{"text":"4 directions:","bold":true},{"text":" "},{"text":"downward","bold":true},{"text":" (manager to employees: goals, instructions, policies); "},{"text":"upward","bold":true},{"text":" (employees to manager: reports, suggestions, complaints); "},{"text":"lateral","bold":true},{"text":" (same level, e.g. cross-functional team); "},{"text":"diagonal","bold":true},{"text":" (across both work areas and levels)."}]},{"text":[{"text":"3 networks:","bold":true},{"text":" "},{"text":"chain","bold":true},{"text":" (formal chain of command; moderate speed, high accuracy); "},{"text":"wheel","bold":true},{"text":" (all through strong central leader; fast, high accuracy, leader emerges strongly, "},{"text":"lowest","bold":true},{"text":" satisfaction); "},{"text":"all-channel","bold":true},{"text":" (everyone talks freely, as in self-managed teams; fast, moderate accuracy, no leader emerges, "},{"text":"highest","bold":true},{"text":" satisfaction)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Managers cannot remove the grapevine: use it as feedback source and limit harmful rumours through open, honest communication."}]},{"text":[{"text":"Managing information:","bold":true},{"text":" first find out what people most want to know (job security, working conditions, reward, location, benefits). "},{"text":"Honesty and feedback","bold":true},{"text":" essential."}]},{"text":[{"text":"IT:","bold":true},{"text":" networked systems link staff by email, instant messaging, voice mail, fax, teleconferencing, videoconferencing, web conferencing. "},{"text":"Wireless:","bold":true},{"text":" staff need not be at desks."}]},{"text":[{"text":"Intranet:","bold":true},{"text":" internet technology inside organization, staff only. "},{"text":"Extranet:","bold":true},{"text":" links it with approved outsiders (customers, suppliers)."}]},{"text":[{"text":"IT gives managers faster, more complete information. Problems: overload, data security, less face-to-face contact."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leadership: influence process; 9 obligations; 7 traits; managers appointed, leaders can emerge."}]},{"text":[{"text":"Behavioural: Iowa, Ohio State, Michigan, Grid (81 positions, 9,9 best). Contingency: Fiedler (fixed), Hersey and Blanchard (readiness), House (path-goal)."}]},{"text":[{"text":"Transactional = rewards for productivity; transformational = inspires extraordinary outcomes."}]},{"text":[{"text":"5 powers; trust built by the 5 Cs."}]},{"text":[{"text":"Communication: 4 functions, 7-part process, 5 types."}]},{"text":[{"text":"6 barriers, 5 remedies, 4 directions, 3 networks."}]}]}],"theory":{"itemId":"cc2c6fa5-15c2-5c75-b5b3-06e96b7c032a","question":[{"type":"paragraph","text":[{"text":"Explain how trust is built in leadership, and discuss three barriers to effective communication in an organization."}]}]},"practice":[{"topic":"Leadership, Trust and Communication","named":false}]}},{"kind":"note","itemId":"4bf7fefb-d37c-5226-85b6-ae5d4e3ebe35","sourceKey":"guide-topic:10","position":10,"payload":{"title":"Foundations of Control and Operations Management","body":"Control, its process, types and tools; operations management; value chain management; quality.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"Control, its process, types and tools; operations management; value chain management; quality."}],"lessons":[{"number":"10.1","title":"Control and the control process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Controlling:","bold":true},{"text":" evaluating progress towards goals by "},{"text":"monitoring, comparing and taking corrective action","bold":true},{"text":", so "},{"text":"actual performance meets planned goals","bold":true},{"text":". It is the "},{"text":"last","bold":true},{"text":" management function. The real test of an effective control system is "},{"text":"whether the organization's goals are being achieved","bold":true},{"text":". Control minimises deviations from standards because it helps managers "},{"text":"check errors and$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 31, $study_guide$ take corrective action","bold":true},{"text":"."}]},{"text":[{"text":"3 reasons control matters:","bold":true},{"text":" (1) the "},{"text":"planning–controlling link","bold":true},{"text":" (control checks planning's goals and feeds new planning); (2) "},{"text":"empowering employees","bold":true},{"text":" (managers delegate without fearing blame for mistakes); (3) "},{"text":"protecting the workplace","bold":true},{"text":" (from disasters, scandals, violence, supply disruption, security breaches, terrorism)."}]},{"text":[{"text":"Control process, 3 steps:","bold":true},{"text":" (1) "},{"text":"measure","bold":true},{"text":" actual performance; (2) "},{"text":"compare","bold":true},{"text":" with the standard; (3) "},{"text":"take managerial action","bold":true},{"text":" (corrective action). Key elements: "},{"text":"setting (establishing) performance standards","bold":true},{"text":" (taken from planning's goals, and the first element of control), "},{"text":"measuring performance, comparing actual results with planned objectives, and taking corrective action","bold":true},{"text":". Performance measurement means comparing actual results with planned objectives."}]},{"text":[{"text":"4 information sources for measuring:","bold":true},{"text":" personal observation, statistical reports, oral reports, written reports."}]},{"text":[{"text":"Range of variation:","bold":true},{"text":" acceptable limits of variance between actual performance and the standard. Act only "},{"text":"outside","bold":true},{"text":" it; watch "},{"text":"size and direction","bold":true},{"text":"."}]},{"text":[{"text":"3 actions:","bold":true},{"text":" (1) do nothing; (2) correct actual performance (e.g. change pay or training); (3) revise the standard (if unrealistic)."}]},{"text":[{"text":"Immediate corrective action:","bold":true},{"text":" corrects at "},{"text":"once","bold":true},{"text":", treats the symptom (same-day overtime). "},{"text":"Basic corrective action:","bold":true},{"text":" asks "},{"text":"how and why","bold":true},{"text":", fixes the "},{"text":"source","bold":true},{"text":" (replace the faulty machine)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Personal observation","bold":true},{"text":" ("},{"text":"MBWA","bold":true},{"text":", management by walking around): first-hand, unfiltered, small details; but biased, slow, looks like distrust. "},{"text":"Statistical:","bold":true},{"text":" graphs show relationships; limited facts, ignore subjective factors. "},{"text":"Oral:","bold":true},{"text":" quick; filtered, no permanent record. "},{"text":"Written:","bold":true},{"text":" comprehensive, formal, easy to file; slower to prepare."}]},{"text":[{"text":"Twin functions:","bold":true},{"text":" planning and control both look at goals (planning sets, control checks), occur at "},{"text":"all levels","bold":true},{"text":", are continuous, use quantitative techniques and standards, and use budgets and ratios."}]},{"text":[{"text":"What","bold":true},{"text":" you measure decides what employees work hard at. Any unit: satisfaction, turnover, absenteeism. Job-specific: units produced, sales. Output hard to count: "},{"text":"subjective","bold":true},{"text":" measures."}]},{"text":[{"text":"Fair standard missed: hold to it and explain; do not lower it."}]},{"text":[{"text":"Trap:","bold":true},{"text":" if every option accurately describes control, \"which does not\" = none of the above."}]}]}]},{"number":"10.2","title":"Types of control and organizational performance","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Feedforward","bold":true},{"text":" (predictive): "},{"text":"before","bold":true},{"text":" the activity; foresee and prevent problems."}]},{"text":[{"text":"Concurrent:","bold":true},{"text":" "},{"text":"during","bold":true},{"text":"; correct problems as they happen."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" "},{"text":"after","bold":true},{"text":" completion; uses performance data to assess whether goals were met."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Strategic control:","bold":true},{"text":" ensures the organization is "},{"text":"moving in the right direction","bold":true},{"text":" by tracking strategy "},{"text":"as it is implemented","bold":true},{"text":", to detect problems or threats."}]},{"text":[{"text":"3 measures of organizational performance:","bold":true},{"text":" (1) "},{"text":"productivity","bold":true},{"text":" (total output ÷ inputs); (2) "},{"text":"effectiveness","bold":true},{"text":" (how appropriate goals are, how well met); (3) "},{"text":"industry and company rankings","bold":true},{"text":" (published lists that rank organizations on set measures)."}]},{"text":[{"text":"Organizational performance:","bold":true},{"text":" combined result of all work activities. More productive = more output from the same or fewer inputs."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Feedforward:","bold":true},{"text":" most "},{"text":"desirable","bold":true},{"text":"; needs timely, accurate information. Examples: inspecting raw materials, training before work, servicing machines."}]},{"text":[{"text":"Concurrent:","bold":true},{"text":" best known is "},{"text":"direct supervision","bold":true},{"text":"; MBWA too."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" most "},{"text":"popular","bold":true},{"text":"; damage already done. Shows how effective "},{"text":"planning","bold":true},{"text":" was; can raise "},{"text":"motivation","bold":true},{"text":" (people want to know how they did). Examples: year-end financial statements, post-sale surveys, exam results."}]}]}]},{"number":"10.3","title":"Control tools and today's control issues","mustKnow":[{"type":"paragraph","text":[{"text":"4 financial ratio groups:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Liquidity","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 32, $study_guide$bold":true},{"text":" (meeting "},{"text":"current, short-term debts","bold":true},{"text":"): current ratio = current assets ÷ current liabilities; acid test = (current assets − inventories) ÷ current liabilities."}]},{"text":[{"text":"Leverage","bold":true},{"text":" (use of "},{"text":"debt","bold":true},{"text":", ability to pay interest): debt to assets = total debt ÷ total assets; times interest earned = profits before interest and taxes ÷ interest charges."}]},{"text":[{"text":"Activity","bold":true},{"text":" ("},{"text":"efficient use","bold":true},{"text":" of assets): inventory turnover = sales ÷ inventory; total asset turnover = sales ÷ total assets."}]},{"text":[{"text":"Profitability","bold":true},{"text":" (assets "},{"text":"generating profit","bold":true},{"text":"): profit margin = net profit after taxes ÷ total sales; return on investment = net profit after taxes ÷ total assets."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Budget:","bold":true},{"text":" a "},{"text":"planning and control","bold":true},{"text":" tool; gives "},{"text":"quantitative standards","bold":true},{"text":"."}]},{"text":[{"text":"MIS (management information system):","bold":true},{"text":" gives managers information "},{"text":"regularly","bold":true},{"text":". "},{"text":"Data","bold":true},{"text":" = raw, unanalysed facts; "},{"text":"information","bold":true},{"text":" = analysed data."}]},{"text":[{"text":"Information controls:","bold":true},{"text":" a "},{"text":"tool","bold":true},{"text":" to control other activities, and an "},{"text":"area to be controlled","bold":true},{"text":" (encryption, firewalls, back-ups)."}]},{"text":[{"text":"Balanced scorecard","bold":true},{"text":" ("},{"text":"Robert Kaplan and David Norton","bold":true},{"text":"): "},{"text":"4 areas","bold":true},{"text":": financial, customer, internal processes, people/innovation/growth assets. Finance alone can hide poor service or staff development."}]},{"text":[{"text":"Benchmarking:","bold":true},{"text":" searching for "},{"text":"best practices","bold":true},{"text":" among competitors or noncompetitors; a "},{"text":"benchmark","bold":true},{"text":" is the standard of excellence compared against. "},{"text":"Xerox:","bold":true},{"text":" first major US effort. "},{"text":"Internal","bold":true},{"text":" benchmarking copies a top unit's practices elsewhere."}]},{"text":[{"text":"4 contemporary control issues:","bold":true},{"text":" (1) cross-cultural differences and global turmoil; (2) workplace concerns (privacy, theft, violence); (3) customer interactions; (4) corporate governance."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Distant global units cannot be observed directly, so controls are more "},{"text":"formal","bold":true},{"text":"."}]},{"text":[{"text":"Employee theft:","bold":true},{"text":" employees' unauthorised taking of company property for own use. Careful hiring and clear policies = feedforward; supervision = concurrent; investigation after theft = feedback."}]},{"text":[{"text":"Service profit chain:","bold":true},{"text":" satisfied employees → better service → customer loyalty → profit."}]},{"text":[{"text":"Corporate governance:","bold":true},{"text":" governing a corporation so "},{"text":"owners' interests are protected","bold":true},{"text":". 2 reform areas: "},{"text":"boards of directors' role","bold":true},{"text":" and "},{"text":"financial reporting","bold":true},{"text":" ("},{"text":"Sarbanes-Oxley Act, 2002","bold":true},{"text":", US)."}]}]}]},{"number":"10.4","title":"Operations management and productivity","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Operations function:","bold":true},{"text":" produces goods or services. "},{"text":"Operations management:","bold":true},{"text":" administration of business structure, practices and processes to "},{"text":"enhance efficiency and maximise profit","bold":true},{"text":"; the "},{"text":"design and control of the transformation process","bold":true},{"text":" (resources into goods and services)."}]},{"text":[{"text":"3 goals:","bold":true},{"text":" controlling costs, maximising profitability, proper allocation of resources."}]},{"text":[{"text":"It "},{"text":"begins and ends with the customer","bold":true},{"text":"; everyone has customers "},{"text":"at the next process","bold":true},{"text":"."}]},{"text":[{"text":"6 functions:","bold":true},{"text":" planning, scheduling, purchasing, controlling, quality control, inventory control."}]},{"text":[{"text":"4 types:","bold":true},{"text":" (1) "},{"text":"manufacturing","bold":true},{"text":" (goods); (2) "},{"text":"service","bold":true},{"text":" (intangible); (3) "},{"text":"logistics","bold":true},{"text":" (movement and storage of goods); (4) "},{"text":"project management","bold":true},{"text":" (a one-off project, planning to completion)."}]},{"text":[{"text":"Transformation process:","bold":true},{"text":" "},{"text":"inputs","bold":true},{"text":" (people, technology, capital, equipment, materials, information) → "},{"text":"transformation","bold":true},{"text":" (work activities, operations methods, management activities) → "},{"text":"outputs","bold":true},{"text":" (goods, services)."}]},{"text":[{"text":"Productivity = outputs ÷ inputs","bold":true},{"text":" (1,200 loaves ÷ 300 labour-hours = 4 per labour-hour)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Operations is vital because of "},{"text":"global competition","bold":true},{"text":", the "},{"text":"rise of the service economy","bold":true},{"text":" and the need for efficient procurement, production and delivery."}]},{"text":[{"text":"Manufacturing:","bold":true},{"text":" physical goods, storable. "},{"text":"Service:","bold":true},{"text":" nonphysical, used as produced (banks, hospitals)."}]},{"text":[{"text":"Productivity needs "},{"text":"both people and operations variables","bold"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 33, $study_guide$:true},{"text":"."}]},{"text":[{"text":"W. Edwards Deming:","bold":true},{"text":" "},{"text":"14 points","bold":true},{"text":" for management's productivity (plan for the "},{"text":"long","bold":true},{"text":" term, drive out fear, break down barriers, statistical control); linked with "},{"text":"TQM","bold":true},{"text":"; early influence in "},{"text":"Japan","bold":true},{"text":"."}]}]}]},{"number":"10.5","title":"Value chain management and quality","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Value:","bold":true},{"text":" features and attributes customers will give up resources (usually money) for."}]},{"text":[{"text":"Value chain:","bold":true},{"text":" the entire series of work activities that "},{"text":"add value at each step","bold":true},{"text":", raw materials to finished product. The "},{"text":"customer","bold":true},{"text":" decides what value is and when."}]},{"text":[{"text":"Value chain management:","bold":true},{"text":" managing activities and information along the "},{"text":"entire","bold":true},{"text":" chain. Goal: meet and exceed customer needs, with "},{"text":"full and seamless integration","bold":true},{"text":" of members. "},{"text":"External","bold":true},{"text":" focus, incoming "},{"text":"and","bold":true},{"text":" outgoing, goal "},{"text":"effectiveness","bold":true},{"text":" (most value for customers)."}]},{"text":[{"text":"Supply chain management:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" focus on efficient flow of "},{"text":"incoming","bold":true},{"text":" materials, goal "},{"text":"efficiency","bold":true},{"text":" (cut costs)."}]},{"text":[{"text":"6 requirements:","bold":true},{"text":" coordination and collaboration; technology investment; organizational processes; leadership; employees; organizational culture and attitudes."}]},{"text":[{"text":"4 obstacles:","bold":true},{"text":" organizational barriers; cultural attitudes; required capabilities; people."}]},{"text":[{"text":"Benefits:","bold":true},{"text":" improved procurement, logistics, product development; enhanced customer order management."}]},{"text":[{"text":"Quality:","bold":true},{"text":" ability of a product or service to reliably do what it should and satisfy customer expectations."}]},{"text":[{"text":"TQM:","bold":true},{"text":" philosophy driven by "},{"text":"continuous improvement","bold":true},{"text":" and responsiveness to customer needs, with employee involvement."}]},{"text":[{"text":"Mass customisation:","bold":true},{"text":" a product when, where, how customers want it."}]},{"text":[{"text":"ISO 9000:","bold":true},{"text":" "},{"text":"international quality management standards","bold":true},{"text":", uniform process guidelines; set by the International Organization for Standardization."}]},{"text":[{"text":"Six Sigma:","bold":true},{"text":" programme to reduce defects, lower costs, save time, improve satisfaction; goal "},{"text":"no more than 3.4 defects per million","bold":true},{"text":" units or procedures."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Obstacles:","bold":true},{"text":" "},{"text":"organizational barriers","italic":true},{"text":" = refusing to share information, resisting change, security worries; "},{"text":"cultural attitudes","italic":true},{"text":" = lack of trust, fear of losing intellectual property; "},{"text":"required capabilities","italic":true},{"text":" = partners lack skills or systems; "},{"text":"people","italic":true},{"text":" = unwilling to change, low commitment, time and energy."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Controlling = monitoring, comparing, correcting; the last function. Process: measure, compare, act (standards come from planning)."}]},{"text":[{"text":"Actions: do nothing, correct (immediate = symptom, basic = cause) or revise the standard."}]},{"text":[{"text":"Feedforward before (most desirable); concurrent during; feedback after (most popular)."}]},{"text":[{"text":"4 control issues: cross-cultural, workplace concerns, customer interactions, corporate governance."}]},{"text":[{"text":"Tools: 4 ratio groups, budget, MIS, balanced scorecard, benchmarking."}]},{"text":[{"text":"Operations: 3 goals, 6 functions, 4 types; productivity = outputs ÷ inputs."}]},{"text":[{"text":"Value chain: external, effectiveness; supply chain: internal, efficiency. Six Sigma: 3.4 per million."}]}]}],"theory":{"itemId":"6d50cf35-2fa6-5b75-87ec-b821597a8811","question":[{"type":"paragraph","text":[{"text":"Define controlling and explain the steps in the control process."}]}]},"practice":[{"topic":"Foundations of Control and Operations Management","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"18575d93-235d-5ae2-971c-dc04634c2596","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"Define management and explain its four functions."},"answer":{"kind":"model_answer","itemId":"d0e7d3fa-6302-5e8c-9a3e-4b6553b8bbd7","sourceKey":"guide-answer:1","payload":{"body":"Define management. Then 1-2 lines each: planning (goals and how to reach them), organizing (structuring work), leading (directing and motivating), controlling (monitoring, comparing, correcting)."}}},{"kind":"theory_question","itemId":"860e6a6e-f521-5acc-9133-ca48c349ee04","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"Distinguish between the classical and socioeconomic views of social responsibility, and explain social obligation, social responsiveness and social responsibility."},"answer":{"kind":"model_answer","itemId":"55d09d3d-b557-5a5e-9faf-2de5c99feedb","sourceKey":"guide-answer:2","payload":{"body":"Classical: stockholder profit (Friedman). Socioeconomic: society's welfare. Obligation: legal and economic duties only. Responsiveness: adapting to societal conditions. Responsibility: ethical commitment beyond law."}}},{"kind":"theory_question","itemId":"b1536dbc-f454-5dad-8fa7-0dae1$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ams101', 34, $study_guide$7d04b05","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Explain the steps in the strategic management process. Distinguish between growth, stability and renewal strategies."},"answer":{"kind":"model_answer","itemId":"3d4abb28-c91f-558e-ae7f-a1058afe4665","sourceKey":"guide-answer:3","payload":{"body":"Define strategic management. Explain the 6 steps, noting SWOT. Define growth, stability and renewal (retrenchment, turnaround), with an example each."}}},{"kind":"theory_question","itemId":"829a57bc-6a83-58b7-8f63-2b5338a3a853","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Explain the six key elements of organizational design."},"answer":{"kind":"model_answer","itemId":"161cbd1a-07b0-5169-93ce-fd07e66d01b4","sourceKey":"guide-answer:4","payload":{"body":"Define organizational design; explain each element in a line or two (departmentalization: five types); conclude: together they decide mechanistic or organic."}}},{"kind":"theory_question","itemId":"07639d6e-7ae4-5601-b110-361c95df96aa","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Explain the HRM process and describe four methods of appraising performance."},"answer":{"kind":"model_answer","itemId":"244a858f-8785-547c-95a7-92c0d54272b9","sourceKey":"guide-answer:5","payload":{"body":"Define HRM; the 8 activities in 3 groups; external factors; four methods."}}},{"kind":"theory_question","itemId":"9c690f6d-55fa-51be-9dca-8e0f4183c11f","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"Explain why employees resist organizational change and discuss the techniques managers can use to reduce resistance."},"answer":{"kind":"model_answer","itemId":"7992673e-7de6-5c77-9adb-6888a0ec601a","sourceKey":"guide-answer:6","payload":{"body":"Define organizational change. Give the 4 reasons for resistance. Explain the 6 techniques with when used and one drawback."}}},{"kind":"theory_question","itemId":"42bbfaf2-990f-56e5-b3bd-ae66a546c271","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Distinguish between a group and a team, and explain the five stages of group development."},"answer":{"kind":"model_answer","itemId":"e0adef81-b4e3-51bc-bdb0-7c25e40f6cee","sourceKey":"guide-answer:7","payload":{"body":"Define each. Give the five differences. Explain each stage in a line."}}},{"kind":"theory_question","itemId":"a46fb73b-a0ea-527f-8974-fb4bb16711f4","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"Explain Herzberg's two-factor theory and state its implications for managers."},"answer":{"kind":"model_answer","itemId":"efb45b36-741d-558b-895a-ac1e0c8da136","sourceKey":"guide-answer:8","payload":{"body":"Hygiene factors (extrinsic: salary, policy, supervision) prevent dissatisfaction only. Motivators (intrinsic: achievement, recognition, responsibility, growth) create satisfaction. Opposite of satisfaction is no satisfaction. Implication: enrich jobs to motivate."}}},{"kind":"theory_question","itemId":"cc2c6fa5-15c2-5c75-b5b3-06e96b7c032a","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"Explain how trust is built in leadership, and discuss three barriers to effective communication in an organization."},"answer":{"kind":"model_answer","itemId":"0379796a-5c19-5543-923b-453d77eeff0c","sourceKey":"guide-answer:9","payload":{"body":"Define trust and why it matters. Give the 5 Cs in one line each. Define communication. Pick three barriers (e.g. filtering, information overload, defensiveness), define each with a workplace example. End with remedies: feedback, simple language, active listening."}}},{"kind":"theory_question","itemId":"6d50cf35-2fa6-5b75-87ec-b821597a8811","sourceKey":"guide-theory:10","position":10,"payload":{"prompt":"Define controlling and explain the steps in the control process."},"answer":{"kind":"model_answer","itemId":"854b201f-015d-53b2-94b2-5e5490980683","sourceKey":"guide-answer:10","payload":{"body":"Define controlling; standards come from planning. (1) Measure, 4 sources; (2) compare, range of variation; (3) act: do nothing, correct (immediate or basic) or revise the standard."}}}]}$study_guide$);
